
'use strict';

$(document).ready(function () {

    $('body').on('click keypress', '.expandable-section-toggler', function () {
        var $container = $(this).parent('.expandable-section-container');
        var $ariaValue = $container.hasClass('is-collapsed');

        $container.toggleClass('is-collapsed').attr('aria-expanded', $ariaValue);
    });

});




