/**
 * Initializes jQuery UI tabs with support for lazy-loading.
 * A particular tab can be initially activated using the optional argument activeTabName.
 * Used by swa:TabsActivationScript.
 *
 * @param activeTabName  {String} optional, forces a particular tab to be selected on init (e.g., '#tab2')
 * @param id  {String} id of the element that serves as the tab container; defaults to 'tabs'
 */
function initTabs(activeTabName, id) {
    const tabsLoaded = {}
    const $tabs = $('#' + (id || 'tabs'))

    $tabs.tabs({
        active: getInitialActiveTabIndex(),
        // run this each time user selects a new tab
        activate: (event, ui) => {
            lazyLoadTab(ui.newPanel.attr('id'))
        },
        // load tab panel contents initially
        create: (event, ui) => {
            event.preventDefault()
            lazyLoadTab(ui.panel.selector.slice(1))
        },
    })

    if ($tabs.is('.swa-tabs')) {
        $tabs.find('.ui-tabs-nav').slick({
            infinite: false,
            slidesToScroll: 1,
            variableWidth: true,
            swipeToSlide: true,
            accessibility: false,
            speed: 300,
        })
    }

    function getInitialActiveTabIndex() {
        if (!activeTabName) return 0
        const index = $tabs.find('a[href="' + activeTabName + '"]').parent().index()
        return index >= 0 ? index : 0
    }

    function lazyLoadTab(tabId) {
        if (!isLoadable(tabId) || tabsLoaded[tabId]) return
        $.when(swa.load(tabId))
            .fail(() => console.log('Could not load tab with id \'' + tabId + '\''))
            .done(() => {tabsLoaded[tabId] = true })
    }

    function isLoadable(id) {
        return $('#' + id).attr('uistate') !== undefined
    }
}

export default initTabs



