/*global swa:true*/
/*global savedQueries:true*/
/*eslint no-console: ["error", { allow: ["warn", "error", "log"] }] */
'use strict';

import $ from 'jquery';
import store from '../redux/store';
import {
    removeSearchFacets,
    applySearchState
} from '../redux/actions';

const openDialog = (viewClass) => {
    let params = {
        _viewClass: viewClass,
        _snippet: true
    };

    let $jqXHR = $.ajax({
        url: swa.server + swa.servlet,
        method: 'GET',
        data: params
    });

    Promise.resolve($jqXHR)
        .then((data) => {
            swa.populateModalDialog(data,null,null,false);
        }, (err) => {
            console.warn(err);
        });
};

/**
* Gets the current search criteria from the current appstate.
* includeLabels: boolean
*  pass true, to send the full searchFacets object
*  pass false, only send a filtered list of facets delimited with ^|
**/
const getCurrentQueryState = (includeLabels) => {
    let queryParams = {};

    if (swa.getAppState().textSearch) {
        queryParams.freeText = swa.getAppState().textSearch;
    }

    if (swa.getAppState().searchFacets.length > 0) {
        if (!includeLabels) {
            let facetString = swa.getAppState().searchFacets.map(facet => facet.selectedFacet).join('^|');
            queryParams.facetFilters = facetString;
        } else {
            queryParams.facetFilters = swa.getAppState().searchFacets;
        }
    }

    return queryParams;
};


$(document).ready(() => {
    if ($('.search-actions-bar').length > 0) {

        $('.search-export').on('click', () => {

            let params = {
                _viewClass: 'savedQueries:SavedSPARQLQueriesExportDialog',
                _snippet: true
            };

            let $jqXHR = $.ajax({
                url: swa.server + swa.servlet,
                method: 'post',
                data: params
            });

            Promise.resolve($jqXHR)
                .then((data) => {
                    swa.populateModalDialog(data,null,null,false);
                }, (err) => {
                    console.warn(err);
                });


        });

        $('.search-reset').on('click', () => {
            store.dispatch(removeSearchFacets());
        });

        $('.search-save').on('click', () => {
            let label = prompt('Name of this query');

            if (label) {

                let params = {
                    _viewClass: 'saf:getSearchQueryService',
                    _snippet: true
                };

                let fullParams = {
                    ...params,
                    ...getCurrentQueryState(false)
                };

                //label, queryValue, saveGraph, queryGraph,format, withImports
                let $jqXHR = $.ajax({
                    url: swa.server + swa.servlet,
                    method: 'GET',
                    data: fullParams
                });

                Promise.resolve($jqXHR)
                    .then(function(data) {
                        return savedQueries.saveQueryRequest(label, data.queryString, 'urn:x-evn-user-data', data.queryGraph, 'json', true, false, JSON.stringify(getCurrentQueryState(true)));
                    },
                    function(jqXHR, textStatus, errorThrown) {
                        console.log(errorThrown);
                    });
            }
        });

        $('.search-open').on('click', () => {
            openDialog('savedQueries:SavedSPARQLQueriesDialog');
        });

        $(document).on('click', '.saved-query-remove', function() {
            var $this = $(this),
                queryURI = $this.attr('data-query-uri'),
                saveGraph = $this.attr('data-save-graph'),
                loadId = $this.attr('data-loadId');

            savedQueries.deleteQuery(queryURI, saveGraph)
                .then(function() {
                    swa.load(loadId);
                });
        });

        $(document).on('click', '.saved-query-execute', function() {
            var $this = $(this),
                queryParams = $this.attr('data-query-params');

            let fullParams = JSON.parse(queryParams);

            if (fullParams) {

                let freeText = fullParams.freeText,
                    selectedFacets = fullParams.facetFilters;

                // build an obj in the format that redux expects...
                let newReduxStateObj = {
                    textSearch: (freeText) ? freeText : '',
                    selectedFacets: (selectedFacets && selectedFacets.length) ? selectedFacets : []
                };

                //dispatch these params in bulk
                store.dispatch(applySearchState(newReduxStateObj));
                // $('#globalModalDialog').modal('hide');
            }

        });

        $(document).on('click', '.saved-query-export', function() {
            var $this = $(this),
                withImports = $this.attr('data-with-imports'),
                graphURI = $this.attr('data-graph-uri'),
                prefixId = $this.attr('data-prefix-id'),
                query = $this.attr('data-query');

            var format = $('#' + prefixId + '-format').val();

            let params = {
                'default-graph-uri': graphURI,
                'query': query,
                'withImports': withImports,
                'format': format
            };

            let strParams = $.param(params);

            var last = document.URL.lastIndexOf('/');
            var URL = document.URL.substring(0, last) + '/sparql';

            window.open(URL + '?' + strParams, '_blank');

        });

    }
});



