/*globals console, document */
'use strict';

var carousel = {

    carouselMarkup : null,
    i : null,
    $carousel : null,
    carouselState : {},

    getFileExtention : function (path) {
        return path.slice((path.lastIndexOf(".") - 1 >>> 0) + 2);
    },


    thumbNailLookup : function (path) {
        var thumbNail;

        switch (true) {
        case (getFileExtention(path) === 'psd'):
            thumbNail = swa.imgPath + 'filetypes/photoshop.png';
            break;
        case (getFileExtention(path) === 'xlsm'):
        case (getFileExtention(path) === 'xlsx'):
        case (getFileExtention(path) === 'xlsb'):
        case (getFileExtention(path) === 'xltx'):
        case (getFileExtention(path) === 'xlt'):
        case (getFileExtention(path) === 'xls'):
            thumbNail = swa.imgPath + 'filetypes/excel.png';
            break;
        case (getFileExtention(path) === 'doc'):
        case (getFileExtention(path) === 'dot'):
        case (getFileExtention(path) === 'wbk'):
        case (getFileExtention(path) === 'docx'):
        case (getFileExtention(path) === 'dotx'):
        case (getFileExtention(path) === 'dotm'):
            thumbNail = swa.imgPath + 'filetypes/msword.png';
            break;
        default:
            thumbNail = swa.imgPath + 'filetypes/unknown.png';
        }

        return thumbNail;
    },


    getImgForType : function (asset) {
        var imgPath;

        // console.log(asset.filepath);

        if (
            (asset.filepath.indexOf('.png') !== -1) ||
            (asset.filepath.indexOf('.jpg') !== -1) ||
            (asset.filepath.indexOf('.JPG') !== -1) ||
            (asset.filepath.indexOf('.jpeg') !== -1) ||
            (asset.filepath.indexOf('.svg') !== -1) ||
            (asset.filepath.indexOf('.gif') !== -1)
        ) {
            // console.log('found an image');
            imgPath = asset.filepath;
        } else {
            imgPath = thumbNailLookup(asset.filepath);
            // console.log('non-image service returned: ' + imgPath);
        }

        return imgPath;
    },


    buildCarouselMarkup : function (collection) {

        var carouselMarkup;

        carouselMarkup = '<ul class="swiper-wrapper">';

        for (i = 0; i < collection.assets.length; i++) {
            var newItem,
                imgSrc = getImgForType(collection.assets[i]),
                altTxt = collection.assets[i]["altText"];

            newItem = '<li class="swiper-slide">' +
                '<a href="' + collection.assets[i]["filepath"] + '" download>' +
                    '<img src="' + imgSrc + '"' +
                    ' alt="' + altTxt + '"  title="' + altTxt + '">' +
                '</a>' +
                '</li>';

            carouselMarkup += newItem;
        }

        carouselMarkup += '</ul>';

        // add pagination
        // carouselMarkup += '<div class="swiper-pagination"></div>';

        // add prev/next arrows
        carouselMarkup += '<div class="swiper-button-prev"></div><div class="swiper-button-next"></div><div class="swiper-scrollbar"></div>';

        return carouselMarkup;
    },


    update : function (updatedWidgetType) {

        switch (updatedWidgetType) {
        case 'swa.search':
        case 'swa.htmlTemplate':

            // get latest data from local swa.dataStore
            carouselState.data = swa.dataStore.getDataForEndpoint(carouselState.$widget.attr('data-widget-endpoint'));

            // exit if there's no assets for the carousel to build off of
            if (carouselState.data.assets === undefined) {
                console.error("Carousel cannot re-init with the data Provided.", carouselState.data);
                break;
            }

            carouselState.$widget.html(buildCarouselMarkup(carouselState.data));

            var $swiperInstance = carouselState.$widget[0].swiper;
            $swiperInstance.destroy(true);
            carouselInit(carouselState);

            break;
        default:
            console.log('Not anything we care about');
        }
    },


    render : function (state) {

        var $widgetContainer = state.$widget,
            collection = state.data,
            carouselMarkup,
            i,
            $carousel;

        if (typeof collection === 'string') {
            $widgetContainer.html('Carousel widget is expecting JSON, but received a string.');
            return true;
        }

        carouselState = state;

        // populate the widget with the prepared markup
        $widgetContainer.addClass('swiper-container').html(buildCarouselMarkup(collection));

        var swiper = new Swiper('.swiper-container', {
            slideToClickedSlide: true,
            a11y: true,
            keyboardControl: true,
            grabCursor: true,
            mousewheelControl: true,
            scrollbar: '.swiper-scrollbar',
            scrollbarHide: true,
            prevButton: '.swiper-button-prev',
            nextButton: '.swiper-button-next',
            centeredSlides: true,
            slidesPerView: 5,
            effect: 'coverflow',
            coverflow: {
                rotate: 50,
                stretch: 0,
                depth: 100,
                modifier: 1,
                slideShadows : false
            }
        });
    }

}

export default carousel;



