import * as registry from './componentRegistry';
import {gadgets} from '../components/swa';

gadgets.Hub.subscribe('org.topbraid.swa.resizeTables', (topic, paneElement) => {

    if(paneElement){
        let component = null;
        paneElement.find('[data-datatable]').each(function(index,item){
            component = registry.getComponent(item.id);

            if(component != null){
                component.reflowTable();
            }

        });
    }
});



