import { swa } from '../components/swa';

swa.dataStore = {

    endpoints: {},

    /**
     * Fetches data for a given endpoint via ajax request
     * @param {string} endpoint - the api service url
     * @param {object} $jqXHR - the XMLHttpRequest object in a jQuery wrapper
     */
    fetchData: function (endpoint) {

        var $jqXHR = $.ajax({
            url: endpoint,
            method: 'get'
        });

        swa.dataStore.endpoints[endpoint] = $jqXHR;

        $.when($jqXHR)
            .fail(function (jqXHR, textStatus, errorThrown) {
                console.error(errorThrown);
            }).done(function (data, textStatus, jqXHR) {
                swa.dataStore.endpoints[endpoint] = data;
            });

        return $jqXHR;

    },

    /**
     * Serve back data from the dataStore, fetching it only when required so multiple requests are not created for the same data
     * @param {string} endpoint - the api service url
     * @param {mixed} data - the data for the given endpoint or a jqXHR if it's currently being fetched
     */
    getDataForEndpoint: function (endpoint) {

    	var newEndpoint = swa.server + swa.servlet + '?' + endpoint + '&_snippet=true';
    	var data;

        //make sure the endpoint is not already being collected
        //if it is, just return the outstanding xhr object
        if (newEndpoint in swa.dataStore.endpoints) {
            data = swa.dataStore.endpoints[newEndpoint];
        } else {
            data = swa.dataStore.fetchData(newEndpoint);
        }

        return data;
    },

    /* TODO; also used in widgetsInit.js, lift the scope of this function */
    hasValue: function  (string) {
        return string !== null && string !== 'undefined' && string !== '';
    },

    /**
     * Processes a change in the system.
     * @param {object} ajaxConfig - a jQuery ajax config object || null, passed along untouched, this should get or post whatever data
     * you need and THEN pass that result object along to the local dataStore so all of the widgets that need it
     * can be updated. If null is passed, an optional fourth param accepts direct input from another widget, this information only persist in memory
     * @todo this should all be wrapped in a Promise object, don't treat jQuery ajax differently
     * @param {string} localDSEndpointToUpdate - the client side dataStore endpoint key which need updating if request is resolved
     * @param {object} $widget - the widget who invoked the change in a jQuery wrapper
     * @param {mixed} directInput - arbitrary input from the user interface, should be sanitized
     */
    processRequest: function (ajaxConfig, localDSEndpointToUpdate, $widget, directInput) {

        var request,
            widgetType = $widget.attr('data-widget-type');

        // console.log('dataStore received a processRequest from a widget of type: ' + widgetType);

        // if it's an ajax config
        if (swa.dataStore.hasValue(ajaxConfig)) {

            request = $.ajax(ajaxConfig);

            $.when(request)
                .fail(function (jqXHR, textStatus, errorThrown) {
                    console.error('There was an error with processRequest for widget of type: ' + widgetType, errorThrown);
                })
                .done(function (data, textStatus, jqXHR) {
                    swa.dataStore.updateData(localDSEndpointToUpdate, data, widgetType);
                });


        } else {

            request = new Promise(function (resolve, reject) {

                try {
                    // probably want to sanitize "directInput" first...
                    resolve(swa.dataStore.updateData(localDSEndpointToUpdate, directInput, widgetType));

                } catch (e) {
                    reject(e);
                }

            });

        }

        return request;


    },

    /**
     * Updates data in the datastore for a given endpoint
     * Then broadcasts out to all widgets the type of widget that made an update
     * @param {string} endpoint - the local endpoint we want to update data for
     * @param {object} data - the data for the given endpoint
     * @param {string} updatingWidgetType - the type of widget that has made the update
     * @param {mixed} the updated data for the endpoint
     */
    updateData: function (endpoint, data, updatingWidgetType) {

        swa.dataStore.endpoints[endpoint] = data;

        $('[data-widget-type]').trigger('widgetUpdate', updatingWidgetType);

        return swa.dataStore.endpoints[endpoint];

    }

};



