/*global swa:true*/
/*eslint no-undef: "error"*/
'use strict';

import React from 'react';
import $ from 'jquery';


let getElementAttr = (el) => {
    return (attr) => {
        return el.attr(attr);
    };
};

class DataTreeComponent extends React.Component {

    constructor(props) {
        super(props);
        this.$treeContainer = $(this.props.domReference);

        this.state = {
            id: undefined,
            link: undefined,
            onLoaded: undefined,
            onSelect: undefined,
            onDoubleClick: false,
            draggable: undefined,
            checkDropFunction: undefined,
            treeMoveHandler: undefined,
            resourceIRI: undefined,
            queryGraphURI: undefined
        };
    }


    componentDidMount() {

        let getTreeAttr = getElementAttr(this.$treeContainer),
            id = getTreeAttr('id'),
            link = getTreeAttr('data-link'),
            onLoaded = getTreeAttr('data-on-loaded'),
            onSelect = getTreeAttr('data-on-select'),
            onDoubleClick = false,
            resourceIRI = getTreeAttr('data-resource-iri'),
            draggable = getTreeAttr('data-draggable') === 'true',
            queryGraphURI = getTreeAttr('data-query-graph-base'),
            checkDropFunction = getTreeAttr('data-check-drop-function') === 'true',
            treeMoveHandler = getTreeAttr('data-tree-move-handler') === 'true';

        this.setState({id, link, onLoaded, onSelect, onDoubleClick, resourceIRI, draggable, queryGraphURI, checkDropFunction, treeMoveHandler});
    }

    shouldComponentUpdate(nextProps, nextState) {
        return nextState.link !== this.state.link;
    }

    componentWillUpdate(nextProps, nextState) {
        swa.initTree(
            nextState.id,
            nextState.link,
            nextState.onLoaded,
            nextState.onSelect,
            nextState.onDoubleClick,
            nextState.draggable,
            nextState.checkDropFunction,
            nextState.treeMoveHandler
        );
    }

    componentDidUpdate() {

        //TODO: explicitly wait for tree to be built before attempting to make API calls against tree.
        setTimeout( () => {
            swa.selectTreeNode(this.state.id, this.state.resourceIRI, this.state.queryGraphURI );
        },500);
    }


    render() {
        return (
            <div className="tree" />
        );
    }

}

export default DataTreeComponent;



