import React from 'react';
import ReactDOM from 'react-dom';
import {swa} from '../components/swa';

var components = {};

export const addComponent = (id, component) => {
    components[id] = component;
};

export const getComponent = (id) => {
    return components[id];
};

export const hasComponent = (id) => {
    return (components[id] ? true : false) ;
};

/**
*  @param container {jQuery Object} The target container that is being destroyed.
*
*/
export const destroyComponent = (container) => {

    if (container && container.length > 0) {
        let node = components[container[0].id];

        if (node && node.$tableContainer) {
            ReactDOM.unmountComponentAtNode(node.$tableContainer[0]);

            if(components[container[0].id]){
                components[container[0].id] = null;
                delete components[container[0].id];
            }
        }
    }
};


/**
 * This bolts the redux datatable functionality to the swa framework.
 * @type { object }
 */
const tableActions = {
    destroyComponent
};

swa.DT = tableActions;



