import React from 'react';
import ReactDOM from 'react-dom';
import store from '../redux/store';
import { resourceChanged } from '../redux/actions';
import * as utils from './Utils';
import 'url-search-params-polyfill';

var padding = {
    padding: 5
};

export default class TBPagination extends React.Component {
    constructor(props) {
        super(props);
        this.state = {
            currentAsset: undefined,
            assetList: undefined,
            listLength: 0,
            currentIndex: 0
        };

        this.showPrevious = this.showPrevious.bind(this);
        this.showNext = this.showNext.bind(this);
        this.getIndex = this.getIndex.bind(this);
        this.addNavListener = this.addNavListener.bind(this);
        this.removeNavListener = this.removeNavListener.bind(this);
        this.componentCleanup = this.componentCleanup.bind(this);


        this.debounceShowPrevious = utils.debounce(this.showPrevious, 500);
        this.debounceShowNext = utils.debounce(this.showNext, 500);
    }

    //Need to get the previous element in the array.
    showPrevious() {
        var currentAsset = this.state.currentAsset;
        var newIndex;
        if (this.state.currentIndex == 0) {
            currentAsset = this.state.assetList[this.state.listLength - 1];
            newIndex = this.state.listLength - 1;
        } else {
            currentAsset = this.state.assetList[this.state.currentIndex - 1];
            newIndex = this.state.currentIndex - 1;
        }

        store.dispatch(resourceChanged('previous resource'));
        this.setState({
            currentAsset,
            currentIndex: newIndex
        });

        this.removeNavListener();

        window.location.href = utils.updateQueryStringParameter(
            window.location.search,
            'resource',
            currentAsset
        );
    }

    //Need to find the next element in the array.
    showNext() {
        var currentAsset = this.state.currentAsset;
        var newIndex;
        if (this.state.currentIndex == this.state.listLength - 1) {
            currentAsset = this.state.assetList[0];
            newIndex = 0;
        } else {
            currentAsset = this.state.assetList[this.state.currentIndex + 1];
            newIndex = this.state.currentIndex + 1;
        }

        store.dispatch(resourceChanged('next resource'));
        this.setState({
            currentAsset,
            currentIndex: newIndex
        });

        this.removeNavListener();

        window.location.href = utils.updateQueryStringParameter(
            window.location.search,
            'resource',
            currentAsset
        );
    }

    getIndex(currentAsset, list) {
        if (list) {
            var i = 0;

            for (i; i < list.length; i++) {
                if (list[i] === currentAsset) break;
            }
            return i;
        }
    }

    componentDidMount() {
        this.addNavListener();

        var list = [];

        if (sessionStorage.getItem('list') === null) {
            list = window.myList;
            sessionStorage.setItem('list', JSON.stringify(list));
        } else {
            var strList = sessionStorage.getItem('list');
            if (strList && strList !== 'undefined') {
                try {
                    list = JSON.parse(strList);
                } catch (err) {
                    //don't report this failure
                }
            }
        }

        var urlParams = new URLSearchParams(window.location.search);
        var currentAsset = urlParams.get('resource');
        var currentIndex = this.getIndex(currentAsset, list);

        this.setState({
            currentAsset: urlParams.get('resource'),
            assetList: list,
            listLength: list ? list.length : 0,
            currentIndex
        });
    }

    componentWillUnmount(){
      this.componentCleanup();
      this.removeNavListener();
    }

    addNavListener(){
      window.addEventListener('beforeunload', this.componentCleanup);
    }

    removeNavListener(){
      window.removeEventListener('beforeunload', this.componentCleanup);
    }

    componentCleanup(){
      if (window.performance && performance.navigation.type == 0) {
         sessionStorage.removeItem('list');
      }
    }

    render() {
        let index =
            this.state.currentIndex + 1 > this.state.listLength
                ? this.state.listLength
                : this.state.currentIndex + 1;
        if (this.state.listLength >= 2) {
            return (
                <div style={padding}>
                    <button
                        className="fa fa-arrow-up btn btn-link"
                        onClick={this.debounceShowPrevious}
                    />
                    <button
                        className="fa fa-arrow-down btn btn-link"
                        onClick={this.debounceShowNext}
                    />
                    <span>
                        {' '}
                        {index} of {this.state.listLength} assets{' '}
                    </span>
                </div>
            );
        }
        return null;
    }
}

$(document).ready(() => {
    let pagination = $('#pagination');
    if (pagination.length > 0) {
        ReactDOM.render(<TBPagination />, document.getElementById('pagination'));
    }
});



