/*global swa:true*/
'use strict';

import $ from 'jquery';
import store from '../redux/store';

$(document).ready(function () {

    // removing facets from app state
    $('.applied-facets-container').on('click', '.criteria-item-container', function () {
        let $facetContainer = $(this),
            isFreeText = $facetContainer.find('span').is('.freeText'),
            isfacetFilter = $facetContainer.find('span').is('.facetFilter');


        if (isFreeText) {
            store.dispatch(swa.actions.removeTextSearch($facetContainer.find('span').attr('data-text')));
        }

        if (isfacetFilter) {
            store.dispatch(swa.actions.removeSearchFacet($facetContainer.find('span').attr('data-uri')));
        }

    });

    store.subscribe(() => {

        // remove the old facets from being shown in the "applied facets container"
        $('.applied-facets-container').find('.criteria-item-container').remove();


        // show freeText filters
        if (store.getState().textSearch !== '') {
            $('.applied-facets-container')
                .append(`
                    <div class="criteria-item-container">
                        <span data-text="${store.getState().textSearch}" class="freeText glyphicon glyphicon-remove" aria-hidden="true"></span>
                        ${store.getState().textSearch}
                    </div>
                `);
        }

        // show facetFilters
        store.getState().searchFacets.forEach((facet) => {
            $('.applied-facets-container').append(`
                <div class="criteria-item-container">
                    <span data-uri="${facet.selectedFacet}" class="facetFilter glyphicon glyphicon-remove" aria-hidden="true"></span>
                    ${facet.label}
                </div>
            `);
        });

    });

});



