/*global swa:true*/
/*eslint no-undef: "error"*/
'use strict';

import $ from 'jquery';
import store from '../redux/store';

$(document).ready(() => {

    let isPageWithSearchInput = $('.search-entry-input').length > 0;

    if (isPageWithSearchInput) {
        // listen for text searches
        $('.search-submit-btn').on('click', () => {
            var searchTerm = $('.search-entry-input').val().trim();
            swa.dispatch(swa.actions.addTextSearch(searchTerm));
        });

        // listen for text enter events
        $('.search-entry-input').on('keypress', function (e) {
            if (e.keyCode === 13) {
                $('.search-submit-btn').click();
            }
        });

        // search input always reflects whatever value is found in the app state
        store.subscribe(() => {
            $('.search-entry-input').val(store.getState().textSearch);
        });
    }
});




