/*globals console, document */

'use strict';

var htmlTemplateRenderer = {

     render : function (state) {

        var $widgetContainer = state.$widget,
            html = state.data;

        if (typeof html === 'object') {
            $widgetContainer.html('HTMLTemplateRenderer widget is expecting HTML, but received an object.');
            return true;
        }

        $widgetContainer = state.$widget;

        $widgetContainer.html(state.data);
    }
}

export default htmlTemplateRenderer;



