import React from 'react';
import Select from 'react-select';
import { CustomOption } from '../utils/select'
import * as utils from './Utils';



export default class TopBraidSelect extends React.Component {
    constructor(props) {
        super(props);

        this.state = {
            removeSelected: true,
            stayOpen: true,
            multi: this.props.multi || undefined,
            clearable: this.props.hasOwnProperty('clearable') ? this.props.clearable : true,
            value: this.props.value || undefined,
            options: this.props.options || undefined,
            placeholder: this.props.placeholder || undefined
        };

        this.handleSelectChange = this.handleSelectChange.bind(this);
        this.handleOnKeyDown = this.handleOnKeyDown.bind(this);
    }

    static getDerivedStateFromProps(nextProps, prevState) {
        let newState = {};

        if (prevState.multi != nextProps.multi && nextProps.multi !== undefined) {
            newState.multi = nextProps.multi;
        }
        if (prevState.clearable != nextProps.clearable && nextProps.clearable !== undefined) {
            newState.clearable = nextProps.clearable;
        }
        if (
            prevState.value != nextProps.value &&
            nextProps.value !== undefined &&
            nextProps.value !== ''
        ) {
            newState.value = nextProps.value;
        }

        if (prevState.options != nextProps.options && nextProps.options !== undefined) {
            newState.options = nextProps.options;
        }

        if (prevState.placeholder != nextProps.placeholder && nextProps.placeholder !== undefined) {
            newState.placeholder = nextProps.placeholder;
        }

        if (Object.keys(newState).length > 0) {
            return newState;
        }

        return null;
    }

    handleSelectChange(value) {
        this.setState(
            {
                value
            },
            () => {
                if (this.props.onChangeCallback) {
                    this.props.onChangeCallback(value);
                }
            }
        );
    }

    handleOnKeyDown(event) {
        if (this.props.onKeyDown) {
            this.props.onKeyDown(event);
        }
    }

    render() {
        return (
            <div className={`${this.props.className ? this.props.className : ''}`}>
                <Select
                    styles={this.props.styles ? this.props.styles : ''}
                    components={{ Option: CustomOption }}
                    className="section"
                    classNamePrefix="section"
                    isMulti={this.state.multi}
                    isClearable={this.state.clearable}
                    onChange={this.handleSelectChange}
                    onKeyDown={this.handleOnKeyDown}
                    options={this.state.options}
                    placeholder={this.state.placeholder}
                    hideSelectedOptions={this.state.removeSelected}
                    value={this.state.value}
                />
            </div>
        );
    }
}



