var swaeditor = {

	elementTreeId : "elementTree",

	getLocalTree : function () {
		return $('#' + this.elementTreeId);
	},

	/**
	 * Validates a jstree drag operation, and determines what happens when a user tries to modify the structure of the tree
     * @description In this tree, there are three types of nodes: root (level 1), groups (level 2) and properties (level 3). The tree can never have more than 3 levels.
     * 1) Root (metadata type of "group") can't be moved.
     * 2) Sections (metadata type of "ObjectsEnum") can be moved to re-arrange their order, but their parent always is the root.
     * 3) Nodes representing properties (metadata type of "Objects") always have a section as their parent. They can be moved within a section to re-arrange their order or they can be moved from one section into another.
	 * @param operation  the type of operation being performed (move_node, copy_node, etc)
	 * @param node  the node being acted on
	 * @param parent  the parent node of the node being hovered over (seems inconsistant)
	 * @param position  the position of the node within the tree
	 * @param more  contains various information provided by the plugin that is invoking the check
	 * @return Returning false prevents operations like create, rename, delete, move and copy, otherwise operation is allowed
	 */
	checkDrop : function(operation, node, parent, position, more) {

		var operationAllowed = true,
			$tree = swaeditor.getLocalTree();

	    switch (operation) {
	        case 'move_node':

	            // more.dnd is active while user is dragging (not on drop)
	            if (more.dnd) {

	                operationAllowed = (
                		swa.checkIfNodeIsDraggable(node) &&
                        !swa.treeNodeIsRoot($tree, node) &&
                        (
                            (swa.checkTreeNodeDepthRemainsSame($tree, node, more.ref) && !swa.checkLandingPosIsInside(more)) ||
                            (swa.dropNodeDepthSameAsParent($tree, more.ref, node.parent) && swa.checkLandingPosIsInside(more))
                        )
                	);

	                return operationAllowed;
	            }

	        break;
	    }

	},

	/**
	 * Creates a node on a tree
	 * @param resourceType  the type of resource to create
	 * @param contextResourceGetter  ???
	 * @param resourceSelectedEvent  the topic to publish after a node has been successfully created
	 */
	createElement : function(resourceType, contextResourceGetter, resourceSelectedEvent) {

		var contextResource = eval(contextResourceGetter);

		if (contextResource && contextResource.indexOf('Error:') == 0) {
			swa.populateModalDialog(contextResource.substring(contextResource.substring(7)));
		} else {
			var params = {
					"_base" : swa.queryGraphURI,
					"_viewClass" : "swaeditor:CreateElementHandler",
					"contextResource" : contextResource,
					"resourceType" : "<" + resourceType + ">"
			}

			var $jqXHR = $.ajax({
				'url': swa.servlet,
				'method': 'get',
				'data': params
			});

			$.when(
				$jqXHR
			).done(function (data, textStatus, jqXHR) {

				swa.processEdits(data, true);
				var resourceURIRaw = data.metadata.createdResource;
				var resourceURI = resourceURIRaw.substring(1, resourceURIRaw.length - 1);
				gadgets.Hub.publish(resourceSelectedEvent, resourceURI);

			}).fail(function (jqXHR, textStatus, errorThrown) {
				swa.populateModalDialog('Operation failed: ' + errorThrown, 'Operation failed', null);
			});
		}
	},

	/**
	 * Delets a node from a tree
	 * @param resourceSelectedEvent  the topic to publish after deleting
	 * this ensures other view know to update themself
	 */
	deleteElement : function(resourceSelectedEvent) {

		var elementResource = swa.getSelectedTreeResource(swaeditor.elementTreeId),
			$jqXHR;

		if (elementResource) {

			var parentElement = swa.getSelectedTreeParentResource(swaeditor.elementTreeId);

			if (!parentElement) {
				swa.populateModalDialog("You cannot delete the root element");
				return;
			}

			var params = {
				"_base" : swa.queryGraphURI,
				"_viewClass" : "swaeditor:DeleteElementHandler",
				"resource" : elementResource
			}

			$jqXHR = $.ajax({
				'url': swa.servlet,
				'method': 'get',
				'data': params
			});

			$.when(
				$jqXHR
			).done(function (data, textStatus, jqXHR) {

				swa.processEdits(data, true);

				if (resourceSelectedEvent) {
					gadgets.Hub.publish(resourceSelectedEvent, parentElement);
				}

			}).fail(function (jqXHR, textStatus, errorThrown) {
				swa.populateModalDialog('Operation failed: ' + errorThrown, 'Operation failed', null);
			});
		}
	},


	/**
	 * A helper that can be called from tree change handlers.
	 * In a typical scenario, handlers walk through a change object to collect
	 * all nodes that need reloading.  Then it triggers a reload.
	 * Similar to swa.handleChangeForTreeHelper
	 * @param change  the change object from the server
	 * @param treeId  the tree id
	 * @param nodeIds  the collection of node ids to reload
	 */
	handleChangesHelper: function (change, treeId, nodeIds) {
	    var numChanges = 0;

	    for (var i in nodeIds) {
	        numChanges++;
	    }

	    if (numChanges > 0) {

	        if (change.metadata && change.metadata.createdResource) {
	            // If it's a new tree node then make sure it's selected after everything has been loaded
	            swa.reloadTreeNodes(treeId, nodeIds);
	            swa.selectTreeNode(treeId, change.metadata.createdResource);

	        } else {
	            swa.reloadTreeNodes(treeId, nodeIds);
	        }
	    }
	},


	/**
	 * Called when an edit has been processed on the server (e.g. via EditForm).
	 * Updates the tree to reflect the changes.
	 * @param change  {Object} information about the change
	 * @param treeId  {String} the id of the tree being acted on
	 */
	handleChanges : function(change, treeId) {

		var tree = $("#" + treeId);
		var $jstree = tree.jstree(true);
		var $changedNodes = null;
		var $addedDeletedNodes = null;

		if (change.changes) {

			var nodeIds = {};

			for (var subjectURI in change.changes) {

				var subjectChanges = change.changes[subjectURI];

				// Children added or deleted
				if (subjectChanges["http://uispin.org/ui#child"] || subjectChanges["-http://uispin.org/ui#child"]) {

					$addedDeletedNodes = tree.find('li[data-resource="' + subjectURI + '"]');

					$addedDeletedNodes.each(function(index, node) {

						var id = $(node).attr('id');
						nodeIds[id] = true;
					});

				}


				// rdf:type, arg:label or arg:predicate changed: update
				if (subjectChanges["http://www.w3.org/1999/02/22-rdf-syntax-ns#type"] ||
						subjectChanges["http://spinrdf.org/arg#label"] ||
						subjectChanges["-http://spinrdf.org/arg#label"] ||
						subjectChanges["http://spinrdf.org/arg#predicate"] ||
						subjectChanges["-http://spinrdf.org/arg#predicate"]) {

					$changedNodes = tree.find('li[data-resource="' + subjectURI + '"]');

					$changedNodes.each(function(index, node) {
						// TODO: this should only update the label, not reload all siblings
						var parentNode = $jstree.get_parent(node);
						nodeIds[parentNode] = true;
					});
				}
			}

			// refresh_node doesn't work here, need to reload_node instead
			swaeditor.handleChangesHelper(change, treeId, nodeIds);

		}
	},


	showSourceCode : function(element) {
		var params = {
				_base : swa.queryGraphURI,
				resource : element.substring(1, element.length - 1)
		};

		var $jqXHR = $.ajax({
	        'url': 'template/swa/GetLabel',
	        'method': 'get',
	        'data': params
	    });

	    $.when(
	    	$jqXHR
	    ).done(function (data, textStatus, jqXHR) {
			var win = $('<div><code><pre id="queryDiv"></pre></code></div>');
			$(win.children()[0]).text(data.results.bindings[0].label.value);
			$(win).dialog({
		        'modal' : true,
		        'title' : 'SWP Source Code',
		        'width' : '800px',
		        'buttons': {
		            'OK': function() {
		                $(this).dialog('close');
		            }
		        }
		    });
	    }).fail(function (jqXHR, textStatus, errorThrown) {
            swa.populateModalDialog('Operation failed: ' + errorThrown, 'Operation failed', null);
	    });

	    return $jqXHR;
	},

	/**
	 * Updates which buttons are available in the form footer
	 * ex: Contextual footer options
	 */
	updateCreateButtons : function() {

		var $tree = $('#' + swaeditor.elementTreeId);

		if (!$tree.jstree(true)) {
			console.warn('The tree "#' + swaeditor.elementTreeId + '" has not been initialized yet');
			return;
		}

		var depth = 0;
		var $jstree = $tree.jstree(true);
		var node = $jstree.get_selected();
		var element = swa.getSelectedTreeResource(swaeditor.elementTreeId);
		var $deleteButton = $("#deleteButton");

		if (node) {

			var path = $jstree.get_path(node);

			depth = path.length;

			if (depth > 1) {
				$deleteButton.show();
			} else {
				$deleteButton.hide();
			}

			if (!element) {
				depth = 0;
			}

			if (node.length > 0 && $jstree.get_node(node[0]).data.metadata == "ObjectsPlaceholder") {
				depth = -1;
			}

		} else {
			$deleteButton.hide();
		}

		$(".swaeditor-create-button").hide();
		$(".level" + depth + "Button").show();
	}
};

export default swaeditor;



