/*global swa:true, teamwork */
import $ from 'jquery';

('use strict');
// short hand for picking off attribute values
export const getElementAttr = el => {
    return attr => {
        return el.attr(attr);
    };
};

export const omit = (obj, omitKey) => {
    return Object.keys(obj).reduce((result, key) => {
        if (key !== omitKey) {
            result[key] = obj[key];
        }
        return result;
    }, {});
};

// performs a post request to swp service with custom params
export const postDataForEndpoint = serviceParams => {
    return $.ajax({
        url: swa.server + swa.servlet,
        data: serviceParams,
        method: 'post',
        _snippet: true
    });
};

// performs a get request to swp service with custom params
export const getDataForEndpoint = serviceParams => {
    return $.ajax({
        url: swa.server + swa.servlet,
        data: serviceParams,
        dataType: 'json',
        method: 'get'
    });
};

// returns query param value from URL
export const getUrlParameter = name => {
    name = name.replace(/[\[]/, '\\[').replace(/[\]]/, '\\]');
    var regex = new RegExp('[\\?&]' + name + '=([^&#]*)');
    var results = regex.exec(location.search);
    return results === null ? '' : decodeURIComponent(results[1].replace(/\+/g, ' '));
};

/*
    Return a function, that, as long as it continues to be invoked, will
    not be triggered. The function will be called after it stops being
    called for `wait` milliseconds.
*/
export const debounce = (fn, time) => {
    let timeout;

    return function() {
        const functionCall = () => fn.apply(this, arguments);

        clearTimeout(timeout);
        timeout = setTimeout(functionCall, time);
    };
};

export const updateQueryStringParameter = (uri, key, value) => {
    var re = new RegExp('([?&])' + key + '=.*?(&|#|$)', 'i');
    if (value === undefined) {
        if (uri.match(re)) {
            return uri.replace(re, '$1$2');
        } else {
            return uri;
        }
    } else {
        if (uri.match(re)) {
            return uri.replace(re, '$1' + key + '=' + encodeURIComponent(value) + '$2');
        } else {
            var hash = '';
            if (uri.indexOf('#') !== -1) {
                hash = uri.replace(/.*#/, '#');
                uri = uri.replace(/#.*/, '');
            }
            var separator = uri.indexOf('?') !== -1 ? '&' : '?';
            return uri + separator + key + '=' + value + hash;
        }
    }
};



