/*global swa:true*/
/*eslint no-undef: "error"*/
'use strict';

import * as actionTypes from './actions-constants';
import { swa } from '../components/swa';

/**
 * Generates an action for changing the value of advanced search state.
 *
 * @param searchBoolean { boolean } Indicates if advanced search is on or off.
 * @returns { {type: String, payload: *} }
 */
export function toggleAdvancedSearch(searchBoolean) {
  return { type: actionTypes.ADVANCED_SEARCH_TOGGLED, payload: searchBoolean };
}

export function togglePrimaryNav(text){
  return {type:actionTypes.PRIMARY_NAV_TOGGLED,payload:text};
}

export function setLanguages(languages) {
  return { type: actionTypes.SET_LANGUAGES, payload: languages };
}

/**
 * Generates an action for adding a search facet to the state.
 *
 * @param facet { string } Value pertaining to what search facet to add. (<http://example.com/predicate> <http://example.com/object>)
 * @returns { {type: String, payload: *} }
 */
export function addSearchFacet(facet) {
  return { type: actionTypes.ADD_SEARCH_FACET, payload: facet };
}

/**
 * Generates an action for removing a search facet from the state.
 *
 * @param facet { string } Value pertaining to what search facet to remove. (<http://example.com/predicate> <http://example.com/object>)
 * @returns { {type: String, payload: *} }
 */
export function removeSearchFacet(facet) {
  return { type: actionTypes.REMOVE_SEARCH_FACET, payload: facet };
}

/**
 * Generates an action for removing all search facets from the state.
 *
 * @returns { {type: String, payload: *} }
 */
export function removeSearchFacets() {
  return { type: actionTypes.REMOVE_ALL_SEARCH_FACETS, payload: null };
}

/**
 * Generates an action for add a text search facet to the state.
 *
 * @param text { string } Value to add to the text search for the state.
 * @returns {{type, payload: *}}
 */
export function addTextSearch(text) {
  return { type: actionTypes.ADD_TEXT_SEARCH, payload: text };
}

/**
 * Generates an action for remove a text search facet from the state.
 *
 * @param text { string } Value to remove from the text search for the state.
 * @returns {{type, payload: *}}
 */
export function removeTextSearch(text) {
  return { type: actionTypes.REMOVE_TEXT_SEARCH, payload: text };
}

/**
 * Generates an action that indicates the active resource (context) has changed
 *
 * @param uri { string } URL/URI of the active resource
 * @returns {{type, payload: *}}
 */
export function resourceChanged(uri) {
  return { type: actionTypes.RESOURCE_CHANGED, payload: uri };
}

export function resourceTypeChanged(uri) {
  return { type: actionTypes.RESOURCE_TYPE_CHANGED, payload: uri };
}

export function setResourceFields(data){
  return {type:actionTypes.SET_RESOURCE_FIELDS, payload:data};
}

export function addSearchFilter(filter) {
  return { type: actionTypes.ADD_SEARCH_FILTER, payload: filter };
}

export function updateSearchFilter(path, value) {
  return { type: actionTypes.UPDATE_SEARCH_FILTER, payload: { path: path, value: value } };
}

export function removeSearchFilter(path, name) {
  return { type: actionTypes.REMOVE_SEARCH_FILTER, payload: {path:path, name:name }};
}

export function removeSearchFilters() {
  return { type: actionTypes.REMOVE_SEARCH_FILTERS, payload: null };
}

export function updateSearchFilterAction(path, value) {
  return { type: actionTypes.UPDATE_SEARCH_FILTER_ACTION, payload: { path: path, value: value } };
}

export function updateSearchFilterLang(path, value) {
  return { type: actionTypes.UPDATE_SEARCH_FILTER_LANG, payload: { path: path, value: value } };
}

export function addSearchColumn(column) {
  return { type: actionTypes.ADD_SEARCH_COLUMN, payload: column };
}

export function removeSearchColumn(column) {
  return { type: actionTypes.REMOVE_SEARCH_COLUMN, payload: column };
}

export function removeSearchColumns(column) {
  return { type: actionTypes.REMOVE_SEARCH_COLUMNS, payload: column };
}

export function removeSearchColumnsAtPath(path) {
  return { type: actionTypes.REMOVE_SEARCH_COLUMNS_AT_PATH, payload:{path:path} };
}

export function searchRequest(item) {
  return { type: actionTypes.SEARCH_REQUEST, payload: item };
}

/**
 * Overrides textSearch and searchFacets state properties
 *
 * @param stateObj { Object } an object that contains textSearch
 * and searchFacets properties to be loaded into the redux state
 * @returns {{type, payload: *}}
 */
export function applySearchState(stateObj) {
  return { type: actionTypes.APPLY_SEARCH_STATE, payload: stateObj };
}

/**
 * Generates an action that adds/updates the searchGraph in use by the application
 *
 * @param searchGraph { string } Value to use as the search graph in the state.
 * @returns {{type, payload: *}}
 */
// export function updateSearchGraph(searchGraph) {
//     return { type: actionTypes.UPDATE_SEARCH_GRAPH, payload: searchGraph };
// }

/**
 * This bolts the redux action functionality to the swa framework.
 * @type { object }
 */
const actions = {
  toggleAdvancedSearch,
  togglePrimaryNav,
  setLanguages,
  addSearchFacet,
  removeSearchFacet,
  removeSearchFacets,
  addTextSearch,
  removeTextSearch,
  resourceChanged,
  resourceTypeChanged,
  setResourceFields,
  addSearchFilter,
  updateSearchFilter,
  updateSearchFilterAction,
  updateSearchFilterLang,
  removeSearchFilter,
  addSearchColumn,
  removeSearchColumn,
  removeSearchFilters,
  removeSearchColumns,
  removeSearchColumnsAtPath,
  searchRequest,
  applySearchState
};

//swa = swa || {};
swa.actions = actions;



