/*global gadgets*/
//FindClassByPropertyDataTableComponent.js
// 'use strict'

import React from 'react';
import $ from 'jquery';
import ReactDOM from 'react-dom';
import store from '../redux/store';
import * as registry from '../utils/componentRegistry';
import { gadgets } from '../components/swa';


class FindClassByPropertyDataTableComponent extends React.Component {

    constructor(props){
        super(props);
    }

    onSelect(e, dt, type, indexes){
        //close and destroy the dialog when a row is clicked
        let div = $('[id$="findDialog"]');
        div.dialog('destroy');
        div.remove();
    }

    render() {
        return(
            <DataTableComponent onSelect={this.onSelect} onDoubleClick={this.onDoubleClick} domReference={this.props.domReference} store={this.props.store} />
        );
    }
}

export default FindClassByPropertyDataTableComponent;

var buildTables = () => {
    let selector = '[data-datatable-type|="findClassByProperty"]';
    let $dataTables = $(selector);
    let component;

    $.each($dataTables, function(idx, table) {
        if(!registry.hasComponent(table.id)){
            component = ReactDOM.render(<FindClassByPropertyDataTableComponent domReference={table} store={store}   />, table);
            registry.addComponent(table.id, component);
        }
    });
};

gadgets.Hub.subscribe('org.topbraid.swa.rebuildTable', () => {
     buildTables();
});



