import React from 'react';
import $ from 'jquery';
import 'datatables.net';
import 'datatables.net-bs';
import 'datatables.net-responsive';
import 'datatables.net-responsive-bs';
import 'datatables.net-fixedheader';
import 'datatables.net-select';
import 'datatables.net-buttons';
import 'datatables.net-buttons-bs';
import JSZip from 'jszip';
window.JSZip = JSZip;
import 'datatables.net-buttons/js/buttons.html5';
import 'datatables.net-buttons/js/buttons.print';
import '../utils/datatablesCommon';
import * as dtConfig from './dataTableConfigs';
import * as dtUtils from './dataTableUtils';
import * as utils from './Utils';
import * as dtEditorButtons from './dataTableEditorButtons';
import 'datatables.net-bs/css/dataTables.bootstrap.css';
import 'datatables.net-responsive-bs/css/responsive.bootstrap.css';
import 'datatables.net-fixedheader-bs/css/fixedHeader.bootstrap.css';
import 'datatables.net-select-bs/css/select.bootstrap.css';
import 'datatables.net-buttons-bs/css/buttons.bootstrap.css';
import '../../lib/dataTablesEditor/css/editor.dataTables.css';
import './datatables.row().show()';

class SimpleDataTableComponent extends React.Component {
    constructor(props) {
        super(props);

        this.store = props.store;
        this.hardBuildRequired = true;
        this.$tableContainer = $(props.domReference);
        this.dataTablesInstance = undefined;

        this.state = {
            resourceType: props.resourceType,
            createService: props.createService,
            createResourceHandler: props.createResourceHandler,
            tableOptions: dtConfig.baseLineConfig,
            data: props.data,
            columns: props.columns
        };

        this.reloadTableData = this.reloadTableData.bind(this);
        this.reInitTable = this.reInitTable.bind(this);
        this.loadingMode = this.loadingMode.bind(this);
        this.buttonsConfig = this.buttonsConfig.bind(this);
        this.attachEvents = this.attachEvents.bind(this);
        this.detachEvents = this.detachEvents.bind(this);
        this.defaultOnSelect = this.defaultOnSelect.bind(this);
        this.reflowTable = this.reflowTable.bind(this);
    }

    buttonsConfig() {
        let editor = undefined,
            buttons = [];

        if (this.props.editable) {
            editor = new $.fn.dataTable.Editor({});

            buttons = buttons.concat(dtEditorButtons.addButtons(this.state, editor, this));
        }

        if (this.props.hasViewDetails) {
            const detailsButton = dtEditorButtons.detailsbutton(this.state, this, editor);

            if (buttons.length > 0) {
                buttons.splice(1, 0, detailsButton);
            } else {
                buttons = buttons.concat(detailsButton);
            }
        }

        if (this.props.buttonConfig) {
            buttons = buttons.concat(this.props.buttonConfig(this.state, editor, this));
        }

        return { buttons: buttons };
    }

    loadingMode(mode) {
        if (mode === true) {
            this.$tableContainer.prepend(
                '<div class="cp-preloader cp-preloader_absolute"><div class="cp-preloader__ball"></div></div>'
            );
        } else {
            this.$tableContainer.find('.cp-preloader').remove();
        }
    }

    reflowTable() {
        this.dataTablesInstance.columns.adjust().responsive.recalc();

        // $(window).resize();
    }

    defaultOnSelect(e, dt, type, indexes) {
        let uri = dt.row(indexes).data().uri;
        this.setState({ curRow: uri });

        //if resource selected event exists, fire
        if (this.state.resourceSelectedEvent) {
            gadgets.Hub.publish(this.state.resourceSelectedEvent, uri);
        }

        //if this is a custom datatable that has a custom onSelect method
        if (this.props.onSelect) {
            this.props.onSelect(e, dt, type, indexes);
        }
    }

    attachEvents(dt) {
        /* on selection of a row */
        dt.on('select', (e, dt, type, indexes) => {
            this.defaultOnSelect(e, dt, type, indexes);
        });

        /* on double click of a row */
        dt.on('dblclick', 'tr', e => {
            e.preventDefault();

            var $cell = $(e.target).closest('td');

            dt.row(`[id="${e.currentTarget.id}"]`).select();

            if (this.props.onDoubleClick) {
                var list = [];

                dt
                    .rows()
                    .data()
                    .each(function(el, idx) {
                        list.push(el.uri);
                    });

                this.props.onDoubleClick(e.currentTarget.id, list);
            }
        });

        if (this.props.hasSelectAll) {
            $(dt.table().header()).on('click', 'th.select-checkbox', () => {
                if ($('th.select-checkbox').hasClass('selected')) {
                    this.dataTablesInstance.rows().deselect();
                    $('th.select-checkbox').removeClass('selected');
                } else {
                    this.dataTablesInstance.rows().select();
                    $('th.select-checkbox').addClass('selected');
                }
            });
        }

        if (this.props.hasFixedToolbar) {
            $('.datatable-toolbar').affix({ offset: { top: 225 } });
        }
    }

    detachEvents(dt) {
        dt.off('select');
        dt.off('dblclick', 'tr');
        $(dt.table().header()).off('click', 'th.select-checkbox');
    }

    reInitTable(config) {
        if (this.dataTablesInstance) {
            this.detachEvents(this.dataTablesInstance);
            this.dataTablesInstance.destroy();
            this.$tableContainer.find('table').empty();
        }

        let dynamicConfig = {
            data: config.data,
            columns: config.columns,
            responsive: this.state.tableOptions.responsive
        };

        if(config.rowId){
          dynamicConfig.rowId = config.rowId;
        }

        if (this.props.hasSelectAll) {
            dynamicConfig.columns.unshift({
                data: null,
                className: 'select-checkbox',
                defaultContent: '',
                orderable: false,
                searchable: false
            });

            dynamicConfig.columns.unshift({
                data: null,
                className: 'control',
                defaultContent: '',
                orderable: false,
                searchable: false
            });

            dynamicConfig.order = [3, 'asc'];

            dynamicConfig.responsive.details.type = 'column';
            dynamicConfig.responsive.details.target = 0;

            dynamicConfig.columnDefs = [
                {
                    className: 'control',
                    targets: 0
                },
                {
                    className: 'select-checkbox',
                    targets: 1
                },
                {
                    target: [0, 1],
                    orderable: false
                }
            ];
        }

        let dom = dtConfig.tableWithToolbarAndLength;

        if (this.props.buttonContainer) {
            dom = dtConfig.tableWithFilter;
        }

        if(this.props.infoCallback){
          dynamicConfig.infoCallback = this.props.infoCallback;
        }

        this.dataTablesInstance = this.$tableContainer.find('table').DataTable({
            ...this.state.tableOptions,
            dom: dom,
            ...this.buttonsConfig(),
            ...dynamicConfig,
            destroy: true
        });

        if (this.props.hasFixedHeader) {
            new $.fn.dataTable.FixedHeader(this.dataTablesInstance);
        }

        if (this.props.buttonContainer) {
            this.dataTablesInstance
                .buttons()
                .container()
                .appendTo(this.props.buttonContainer);
        }

        this.attachEvents(this.dataTablesInstance);
    }

    reloadTableData(data) {
        if (this.dataTablesInstance) {
            this.dataTablesInstance.clear();
            if (data !== undefined) {
                this.dataTablesInstance.rows.add(data).draw();

                if (this.state.curRow) {
                    this.dataTablesInstance.row(`[id="${this.state.curRow}"]`).select();
                }
            }
        }
    }

    shouldComponentUpdate(nextProps) {
        if (this.props.columns.length != nextProps.columns.length) {
            this.reInitTable(nextProps);
            return false;
        } else {
            for (let i = 0; i < this.props.columns.length; i++) {
                if (this.props.columns[i] && nextProps.columns[i]) {
                    if (
                        this.props.columns[i].data !== nextProps.columns[i].data ||
                        this.props.columns[i].title !== nextProps.columns[i].title ||
                        this.props.columns[i].type !== nextProps.columns[i].type
                    ) {
                        this.reInitTable(nextProps);
                        return false;
                    }
                }
            }
        }

        if (this.props.data !== nextProps.data) {
            this.reloadTableData(nextProps.data);
        }
        return false;
    }

    componentDidMount() {
        this.reInitTable(this.props);
    }

    componentWillUnmount() {
        if (this.dataTablesInstance) {
            this.dataTablesInstance.destroy(true);
            this.dataTablesInstance = null;
        }
    }

    componentWillReceiveProps(nextProps) {
        let newProps = {};

        if (this.props.data != nextProps.data) {
            newProps.data = nextProps.data;
        }

        if (this.props.resourceType != nextProps.resourceType) {
            newProps.resourceType = nextProps.resourceType;
        }

        if(this.props.createService != nextProps.createService){
          newProps.createService = nextProps.createService;
        }

        if(this.props.createResourceHandler != nextProps.createResourceHandler){
          newProps.createResourceHandler = nextProps.createResourceHandler;
        }

        if (Object.keys(newProps).length > 0) {
            this.setState(newProps);
        }
    }

    render() {
        return (
            <div>
                <table
                    className="table table-striped table-bordered hover table-condensed"
                    width="100%"
                />
            </div>
        );
    }
}

export default SimpleDataTableComponent;



