import $ from 'jquery';
import {swa} from '../components/swa';

'use strict';
$(document).ready(function () {

    var osType = swa.detectOsType(),
        pageType = $('#header').attr('data-page-type');

	$('body').attr('data-os-type', osType).attr('data-page-type', pageType);

    $('.fancy').chosen({
        disable_search_threshold: 4,
        no_results_text: "No results found"
    });
});





