/*global swa:true, teamwork gadgets */
/*DataTable configuration options */
import '../../../topbraid/lib/dataTablesEditor/js/dataTables.editor';
import * as editorButtons from './dataTableEditorButtons';

('use strict');

export const tblIdSrc = 'uri';
export const tblRowId = 'uri';

export const simpleTableConfig =
    '<"row"<"col-sm-12 no-gutters"tr>>' + '<"row"<"col-lg-5"i><"col-lg-7"p>>';

export const tableWithToolbarConfig =
    '<"datatable-toolbar-wrapper"<"row datatable-toolbar"<"row"<"col-sm-4"f><"col-sm-8 text-right"B>>">>' +
    '<"row"<"col-sm-12 no-gutters"tr>>' +
    '<"row"<"col-lg-5"i><"col-lg-7"p>>';

export const tableWithToolbarAndLength =
    '<"datatable-toolbar-wrapper"<"row datatable-toolbar"<"col-sm-12 text-right"B>">>' +
    '<"row"<"col-sm-6"l><"col-sm-6"f>>' +
    '<"row"<"col-sm-12 no-gutters"tr>>' +
    '<"row"<"col-lg-5"i><"col-lg-7"p>>';

export const tableWithFilter =
    '<"row"<"col-sm-6"l><"col-sm-6"f>>' +
    '<"row"<"col-sm-12 no-gutters"tr>>' +
    '<"row"<"col-lg-5"i><"col-lg-7"p>>'; // +
//'<"row"<"col-sm-12 text-right"B>>';

// baseline table options
export const baseLineConfig = {
    responsive: {
        details: {
            type: 'inline'
        }
    },
    select: {
        info: true,
        items: 'row',
        style: 'os',
        selector: 'td:not(.control)'
    },
    rowId: tblRowId,
    idSrc: tblIdSrc,
    destroy: true,
    pageLength: 25,
    pagingType: 'simple',
    language: {
        search: '<strong>Refine:</strong>',
        sInfo: '_START_ to _END_ of _TOTAL_ entries'
    },
    columns: [],
    columnDefs: [{ className: 'desktop', targets: [1] }],
    data: {},
    order: [1, 'asc'] //cannot hardcode this if we want to be able to update order of columns
};

export const verticalScrollConfig = {
    scrollY: '30vh',
    scrollCollapse: true
};

// adds an initial column of checkboxes to the table
export const checkBoxSelectionConfig = () => {
    return {
        data: null,
        defaultContent: '',
        className: 'select-checkbox',
        width: 20,
        orderable: false,
        visible: true,
        searchable: false
    };
};

//adds select all/select none buttons
export const selectAllConfig = () => {
    return [
        {
            extend: 'selectAll',
            text: 'Select All',
            action: function(e, dt) {
                dt.rows({ search: 'applied' }).select();
            }
        },
        {
            extend: 'selectNone',
            text: 'Deselect all'
        }
    ];
};

export const customButtonsConfig = state => {
    let buttons = JSON.parse(state.hasCustomBtns);

    return buttons.map(btn => {
        return {
            text: btn.btnText,
            action: (e, dt) => {
                let selectedRows = dt.rows({ selected: true }),
                    selectedResources = [];

                if (selectedRows) {
                    let i;
                    for (i = 0; i < selectedRows.count(); i++) {
                        selectedResources.push(selectedRows.data()[i].uri);
                    }
                }

                gadgets.Hub.publish(btn.eventTopic, { selectedResources });
            }
        };
    });
};

export const exportColumnConfig = state => {
    if (state.onlyExportVisibleColumns) {
        return [
            {
                extend: 'excel', //requires JSZip
                exportOptions: {
                    columns: ':visible'
                }
            },
            {
                extend: 'csv',
                exportOptions: {
                    columns: ':visible'
                }
            },
            {
                extend: 'print',
                exportOptions: {
                    columns: ':visible'
                }
            }
        ];
    } else {
        return [
            'excel', // requires JSZip
            'csv',
            'print'
        ];
    }
};

export const buildColumnsData = (columnsArray, addCheckbox) => {
    //injects checkbox column data if it's needed
    return addCheckbox ? [checkBoxSelectionConfig(), ...columnsArray] : columnsArray;
};

export const customColumnDefs = state => {
    if (state.customColumnDefs) {
        let columnDefs = JSON.parse(state.customColumnDefs);

        if (columnDefs && columnDefs.length > 0) {
            state.tableOptions.columnDefs = columnDefs;
        }
    }
    return state;
};



