import 'core-js/fn/object/assign';
import React from 'react';
import ReactDOM from 'react-dom';
import PropTypes from 'prop-types';
import {VictoryTheme, VictoryContainer, VictoryLegend, VictoryPie, VictoryTooltip, Slice, VictoryLabel } from 'victory';
import * as chartUtil from './chartUtil';
import TopBraidLoading from '../loading';
import Message from '../message';


class CustomLabel extends React.Component {
  render() {

    return (
      <g>
        <VictoryLabel {...this.props} style={{fontSize:18}} text={this.props.datum.y}/>
        <VictoryTooltip
          {...this.props}
          orientation={'bottom'}
          x={155} y={5}
          style={{fontSize:14}}
          text={reflowWord(this.props.text)}
          textAnchor="middle"
          pointerLength={0}
        />
      </g>
    );
  }
}

CustomLabel.defaultEvents = VictoryTooltip.defaultEvents;
CustomLabel.propTypes = { text: PropTypes.string };


const reflowWord = (word) => {
    return chartUtil.getLines(chartUtil.wordsWidth(word), 200,{fontSize:12});
}

const reflowLegend = (data) => {
  var legend = [];

  if(data.legend){
    for(var i in data.legend){
       var lines = reflowWord(data.legend[i].name)
       legend.push({name: lines.join('\n')});
    }
  }

  return legend;

}

class TopBraidDonutChart extends React.Component {
  constructor(props){
      super(props);
      this.$container = $(this.props.domReference);
      this.state = {
          data:undefined
      };
    }

    componentDidMount() {
        var getAttr = chartUtil.getElementAttr(this.$container),
            dataService = getAttr('data-endpoint'),
            subjectArea = getAttr('data-subjectArea');

        if (dataService != null) {
            var requestData = {
                _viewClass: dataService ,
                subjectArea: subjectArea
            }
            var jqXHR = chartUtil.getDataFromService(requestData);

            jqXHR.then((data) => {
              //the legend data may be too large
              data.legend = reflowLegend(data);

              this.setState({data: data});

            }, (err) => {

            });
        }
    }

  render() {

  if(!this.state.data){
    return (
       <TopBraidLoading />
    );
  }

    if(this.state.data.hasOwnProperty('message')){
     return (<Message className={'no-chart'} value={this.state.data.message} />)
   }

  return (
      <div className="clearfix" style={{height:'100%',width:'100%'}}>

        <div style={{display:'inline-block'}}>
          <svg width={310} height={310}>
            <VictoryPie
              height={310}
              width={310}
              standalone={false}
              theme={VictoryTheme.material}
              innerRadius={60}
              labelRadius={80}
              labels={(d) => d.y}
              labelComponent={<CustomLabel/>}
              data={this.state.data.slices}
            />

            <VictoryLabel
              x={155} y={155}
              style={{fontSize:32}}
              textAnchor="middle"
              text={this.state.data.total}
            />
          </svg>
        </div>

        <VictoryLegend
          orientation='vertical'
          gutter={2}
          y={10}
          x={10}
          containerComponent={<VictoryContainer responsive={false} width={225} style={{ display:'inline-block'}}/>}
          theme={VictoryTheme.material}
          style={{ border: { stroke: "black" }, title:{fontSize:12} }}
          data={this.state.data.legend}/>

      </div>
    )
  }
}


export default TopBraidDonutChart;



