'use strict';
import $ from 'jquery';
import store from '../redux/store';
import {toggleAdvancedSearch} from '../redux/actions';

$(document).ready(function () {

    $('input[type=checkbox].advanced-search').on('change', function () {
        store.dispatch(toggleAdvancedSearch($(this).is(':checked')));
    });

    store.subscribe(function () {
        $('input[type=checkbox].advanced-search').prop('checked', store.getState().advancedSearch);
    });

});



