import React from 'react';
import ReactDOM from 'react-dom';
import $ from 'jquery';

import {gadgets} from '../swa';
import TopBraidDonutChart from './donutChart';
import TopBraidStackChart from './stackChart';


var buildDonutCharts = (charts) => {
  if(charts != null){
    $.each(charts,function(idx,chart){
        ReactDOM.render(<TopBraidDonutChart domReference={chart}/>, chart);
    });
  }
};

var buildStackCharts = (charts) => {
  if(charts != null){
    $.each(charts,function(idx,chart){
        ReactDOM.render(<TopBraidStackChart domReference={chart}/>, chart);
    });
  }
};


var initCharts = () => {

  var charts = $('[data-chart="donut"]');
  buildDonutCharts(charts);

  charts = $('[data-chart="stack"]');
  buildStackCharts(charts);

};


gadgets.Hub.subscribe('swa.victory.chart.donut.loaded', (topic, chart) => {
    var charts = $(`[id="${chart}"][data-chart="donut"]`);
    buildDonutCharts(charts);
});

gadgets.Hub.subscribe('swa.victory.chart.stack.loaded', (topic, chart) => {
  var charts = $(`[id="${chart}"][data-chart="stack"]`);
  buildStackCharts(charts);
});



