import React from 'react';
import ReactDOM from 'react-dom';
import $ from 'jquery';

import DataTreeComponent from './dataTree';

$(document).ready(() => {
    buildTrees();
});

var buildTrees = () => {
    let $dataTrees =  $('[data-datatree]');

    $.each($dataTrees, function (idx, tree) {
        ReactDOM.render(<DataTreeComponent domReference={tree}/>, tree);
    });
};



