'use strict'

import $ from 'jquery';
import { TextSize } from 'victory';

export const getElementAttr = (el) => {
    return (attr) => {
        return el.attr(attr);
    };
};


export const getDataFromService = (params) => {
    if (params != null) {

        return $.ajax({
            url: swa.server + swa.servlet,
            dataType: 'json',
            method: 'get',
            data: params
        });

    }
};

const hasWhiteSpace = (word) => {
   return /\s/g.test(word.trim());
}

export const wordsWidth = (word,maxWordLength) => {
   if(!hasWhiteSpace(word)){
     maxWordLength = maxWordLength | 20;
     var pattern = new RegExp('.{1,' + maxWordLength + '}', 'g');
     var breakDown = word.match(pattern);

     word = breakDown.join(' ');
   }

   const words = word.split(/\s+/);

   return words.map(word => {
      var size = TextSize.approximateTextSize(word, {fontSize:12});
     return { word, width: size.width }
   });

};

export const getLines = (words, lineWidth, style) => {

   const space = '\u00A0'; // Unicode space
   const spaceWidth =  TextSize.approximateTextSize(space, style).width;


   var wordsByLines =  words.reduce((result, { word, width}) => {

    const lastLine = result[result.length - 1] || { words: [], width: 0 };

    if (lastLine.words.length === 0) {
      // First word on line
      const newLine = { words: [word], width };
      result.push(newLine);
    } else if (lastLine.width + width + (lastLine.words.length * spaceWidth) < lineWidth) {
      // Word can be added to an existing line
      lastLine.words.push(word);
      lastLine.width += width;
    } else {
      // Word too long to fit on existing line
      const newLine = { words: [word], width };
      result.push(newLine);
    }

    return result;
  }, []);



   return wordsByLines.map(line => line.words.join(' '));
};



