/*global  swa:true, gadgets*/
/*eslint no-undef: "error"*/

import React from 'react';
import ReactDOM from 'react-dom';
import $ from 'jquery';
import store from '../redux/store';
import { gadgets } from '../components/swa';
import * as registry from '../utils/componentRegistry';
import DataTableComponent from './dataTable';


var buildTables = (sel) => {

    let selector = sel || '[data-datatable-type|="dataTable"]';
    let $dataTables = $(selector);

    let component;
    $.each($dataTables, function(idx, table) {
        if(!registry.hasComponent(table.id)){
            component = ReactDOM.render(<DataTableComponent domReference={table} store={store} />, table);
            registry.addComponent(table.id, component);
        }
        else{
            registry.destroyComponent($(table));
            component = ReactDOM.render(<DataTableComponent domReference={table} store={store} />, table);
            registry.addComponent(table.id, component);
        }

    });
};

// build any tables that exist as part of markup delivered by the server
$(document).ready(() => {
    buildTables();
});

gadgets.Hub.subscribe('org.topbraid.swa.comparisonMatrixReady', (e, id) => {
    buildTables(`[id="${id}"] [data-datatable]`);
});

gadgets.Hub.subscribe('org.topbraid.swa.rebuildTable', (topic, id) => {
    buildTables(`[id="${id}"][data-datatable-type|="dataTable"]`);
});

gadgets.Hub.subscribe('org.topbraid.swa.change', () => {
    buildTables();
});




