// Helper function called when the user clicks the Add button on a property marked as swa:blankNodeProperty
swa.addBlankNodeObjectEditorRow = function(
    queryGraphURI,
    bodyId,
    single,
    subjectURI,
    predicateURI,
    appName
) {
    var params = {
        _base: queryGraphURI,
        _snippet: true,
        _viewClass: 'swa:ObjectEditorRow',
        predicate: '<' + predicateURI + '>',
        subject: '<' + subjectURI + '>'
    };
    if (appName) {
        params['_contextswaAppName'] = '"' + appName + '"';
    }

    var $jqXHR = $.ajax({
        url: swa.servlet,
        method: 'get',
        data: params
    });

    $.when($jqXHR)
        .done(function(data, textStatus, jqXHR) {
            $('#' + bodyId).append(data);
            if (single) {
                $('#' + bodyId)
                    .prev()
                    .find('.swa-add-button-div')
                    .each(function(i, item) {
                        $(item).addClass('swa-display-none');
                        $(item).removeClass('swa-icon');
                    });
            }
        })
        .fail(function(jqXHR, textStatus, errorThrown) {
            swa.populateModalDialog('Operation failed: ' + errorThrown, 'Operation failed', null);
        });

    return $jqXHR;
};

// Helper function used to either insert a new row to either an object widget or a subject widget.
swa.addEditorRow = function(
    queryGraphURI,
    bodyId,
    single,
    viewClass,
    predicateURI,
    params,
    appName,
    range
) {
    params._base = queryGraphURI;
    params._snippet = true;
    params._viewClass = viewClass;
    params.predicate = '<' + predicateURI + '>';
    if (appName && appName != '') {
        params['_contextswaAppName'] = '"' + appName + '"';
    }
    if (range) {
        params.range = range;
    }

    var $jqXHR = $.ajax({
        url: swa.server + swa.servlet,
        method: 'get',
        data: params
    });

    $.when($jqXHR)
        .done(function(data, textStatus, jqXHR) {
            $('#' + bodyId).append(data);
            if (single) {
                $('#' + bodyId)
                    .parent()
                    .parent()
                    .find('.swa-add-button-div')
                    .each(function(i, item) {
                        $(item).addClass('swa-display-none');
                        $(item).removeClass('swa-icon');
                    });
            }
        })
        .fail(function(jqXHR, textStatus, errorThrown) {
            swa.populateModalDialog('Operation failed: ' + errorThrown, 'Operation failed', null);
        });

    return $jqXHR;
};

