/*globals window, jQuery, $, document, NeighborGram, neighborGram, swa, gadgets */

'use strict';

var neighborGramInit = function () {
        var options = NeighborGram.getDefaultProperties();

        var dataProvider = NeighborGram.getDefaultDataProvider(
            swa.servlet,
            swa.neighborgram.base,
            "swa:NeighborGramPropertiesDataService"
        );

        // initialize the neighborgram component
        var neighborGram = NeighborGram.create(
            "graphPlace",
            dataProvider,
            swa.neighborgram.focusNodeUri,  // url of the central element // node
            swa.neighborgram.resourcePath,
            options
        );

        new NeighborGram.uiUtils.DefaultUI({
        	lineageGram: neighborGram,
        	baseElement: 'tqLgDefaultUI',
        	legends: [ // List of legends which contains icons, labels and descriptions.
        		{
        			'image': swa.neighborgram.resourcePath + '/images/svg/properties.svg',// image of the legend-tem
        			'label': 'Navigation properties',       // text under the image of the legend-tem
        			'description': 'Description: Navigation properties' // will be represented as a title (tooltip)
        		},
        		{
        			'image': swa.neighborgram.resourcePath + '/images/svg/expand.svg',
        			'label': 'Expand node',
        			'description': 'Description: Expand node'
        		},
        		{
        			'image': swa.neighborgram.resourcePath + '/images/svg/collapse.svg',
        			'label': 'Collapse node',
        			'description': 'Description: Collapse node'
        		}
        	]
        });

        // Searching
        var searchObj = null;
        $('#tqNgSearch').autocomplete({
        	source: function (request, callback) {
        		var result = neighborGram.getNodes().filter(function (node) {
        			return node.dataModel.label && node.dataModel.label.toLowerCase().indexOf(request.term.toLowerCase()) !== -1;
        		})
        		.map(function (node) {
        			return {
        				label: node.dataModel.label,
        				value: node.dataModel.typeId
        			};
        		});
        		callback(result);
        	},
        	select: function (event, selectedElement) {
        		event.preventDefault();
        		searchObj = selectedElement.item;
        		neighborGram.setFocusNode(searchObj.value);
        		this.value = searchObj.label;
        	},
        	focus: function (event, selectedElement) {
        		event.preventDefault();
        		searchObj = selectedElement.item;
        		this.value = searchObj.label;
        	},
        	search: function () {
        		searchObj = null;
        	}
        });

        var updatePage = function(focusNode) {
            var myNode = document.getElementById("selectedNode");

            if (myNode) {
            while (myNode.firstChild) {
                myNode.removeChild(myNode.firstChild);
            }

            myNode.appendChild(document.createTextNode(focusNode
                ? "NeighborGram™ for " + focusNode.dataModel.label
                : "No node selected"));
            }

            if (focusNode) {
                gadgets.Hub.publish('org.topbraid.neighborGram.nodeFocused', focusNode.dataModel.typeId);
            }
        };

        neighborGram.onNodeFocused(function (node) {
        	updatePage(node);
        });

        neighborGram.onStateChanged(function (state) {
        	updatePage(state.rootNode);
        });

        // neighborGram.onNodeSelected(function(node){
        //     //called when user selects a node
        //     console.log(node);
        // });

        // attach neighborGram to the global window object
        // so you can call its functions from outside this closure
        window.neighborGram = neighborGram;
    };


$(document).ready(function () {

  if(typeof NeighborGram !== 'undefined'){
    neighborGramInit();
  }

});



