/*global swa:true, gadgets, teamwork*/
/* eslint no-undef: "error" */
/*eslint no-console: ["error", { allow: ["warn", "error", "log"] }] */
'use strict';

import React from 'react';
import $ from 'jquery';
import 'datatables.net';
import 'datatables.net-bs';
import 'datatables.net-responsive';
import 'datatables.net-responsive-bs';
import 'datatables.net-fixedheader';
import 'datatables.net-select';
import 'datatables.net-buttons';
import 'datatables.net-buttons-bs';
import JSZip from 'jszip';
window.JSZip = JSZip;
import 'datatables.net-buttons/js/buttons.html5';
import 'datatables.net-buttons/js/buttons.print';
import '../../lib/dataTablesEditor/js/dataTables.editor';
import '../utils/datatablesCommon';
import * as dtConfig from './dataTableConfigs';
import * as dtUtils from './dataTableUtils';
import * as utils from './Utils';
import * as dtEditorButtons from './dataTableEditorButtons';
import 'datatables.net-bs/css/dataTables.bootstrap.css';
import 'datatables.net-responsive-bs/css/responsive.bootstrap.css';
import 'datatables.net-fixedheader-bs/css/fixedHeader.bootstrap.css';
import 'datatables.net-select-bs/css/select.bootstrap.css';
import 'datatables.net-buttons-bs/css/buttons.bootstrap.css';
import '../../lib/dataTablesEditor/css/editor.dataTables.css';
import './datatables.row().show()';

class DataTableComponent extends React.Component {
    constructor(props) {
        super(props);
        this.dataTablesInstance = undefined;
        this.store = props.store;
        this.$tableContainer = $(this.props.domReference);
        this.hardBuildRequired = true;
        this.editor = undefined;
        this.lastServiceRequests = undefined;
        this.initialStateConfig = undefined;

        this.state = {
            tableOptions: dtConfig.baseLineConfig,
            dataService: undefined,
            columnsService: undefined,
            isEditable: undefined,
            hasFilter: undefined,
            hasViewDetails: undefined,
            hasCloneButton: undefined,
            dataParams: {},
            colParams: {},
            fieldParams: {},
            createService: undefined,
            createResourceHandler: undefined,
            searchGraph: undefined,
            limit: undefined,
            queryParam: undefined,
            queryParamValues: undefined,
            curRow: undefined,
            detailsViewClass: undefined,
            successfullyResolved: undefined
        };

        // rebuilds the table conservatively
        this.buildDataTable = this.buildDataTable.bind(this);

        // displays a loading indicator
        this.loadingMode = this.loadingMode.bind(this);

        //bind default on select
        this.defaultOnSelect = this.defaultOnSelect.bind(this);

        //bind default on double click
        this.defaultOnDoubleClick = this.defaultOnDoubleClick.bind(this);

        //bind default add button function
        this.defaultAddButtons = this.defaultAddButtons.bind(this);

        //fixed header helper methods
        this.initFixedHeader = this.initFixedHeader.bind(this);
        this.cleanupFixedHeader = this.cleanupFixedHeader.bind(this);

        //handles how to fetch data
        this.loadComponentData = this.loadComponentData.bind(this);

        // primary function in charge of updating the component state
        this.updateComponentState = this.updateComponentState.bind(this);

        // make this component aware of changes to the redux state
        this.unsubscribe = this.store.subscribe(this.updateComponentState);
    }

    componentDidMount() {
        var getTableAttr = utils.getElementAttr(this.$tableContainer),
            initialStateConfig = {
                tableOptions: {
                    ...this.state.tableOptions
                },
                dataService: getTableAttr('data-endpoint'),
                columnsService: getTableAttr('data-columns-endpoint'),
                columnData: getTableAttr('data-column-data'),
                dataData: getTableAttr('data-data-data'),
                createService: getTableAttr('data-create-service'),
                createResourceHandler: getTableAttr('data-create-service-handler'),
                dtType: getTableAttr('data-datatable-type'),
                fromDom: getTableAttr('data-from-dom'),
                detailsViewClass: getTableAttr('data-details-view-class'),
                hasViewDetails: getTableAttr('data-viewable-details'),
                hasSelectAll: getTableAttr('data-has-select-all'),
                hasExports: getTableAttr('data-has-exports'),
                hasCloneButton: getTableAttr('data-has-clone-button'),
                hasEditButton: getTableAttr('data-has-edit-button'),
                hasFilter: getTableAttr('data-has-filter'),
                hasMultiSelect: getTableAttr('data-multiselect'),
                resourceSelectedEvent: getTableAttr('data-resource-selected-event'),
                resourceType: getTableAttr('data-resource-type'),
                hasComparisonMatrix: getTableAttr('data-has-comparison-matrix'),
                cmViewClass: getTableAttr('data-comparison-matrix-view-class'),
                cmBaseGraph: getTableAttr('data-comparison-matrix-base-graph'),
                hasScrollCollapse: getTableAttr('data-scroll-collapse'),
                hasFixedHeader: getTableAttr('data-has-fixed-header'),
                hasCustomBtns: getTableAttr('data-custom-btn-events'),
                customColumnDefs: getTableAttr('data-custom-column-defs'),
                isEditable: getTableAttr('data-editable') === 'true',
                tableId: getTableAttr('id'),
                dataParams: {},
                colParams: {},
                fieldParams: {},
                scrollParams: getTableAttr('data-scrollx'),
                searchGraph: getTableAttr('data-search-graph'),
                limit: getTableAttr('data-limit'),
                queryParam: getTableAttr('data-init-query-param'),
                queryParamValues: getTableAttr('data-init-query-param-values'),
                hasWorkflowHome: getTableAttr('data-workflow-home'),
                hasWorkflowAsset: getTableAttr('data-has-workflow-asset'),
                hasTransitionHistory: getTableAttr('data-transition-history'),
                hasArchiveConfig: getTableAttr('data-workflow-archive'),
                hideIfEmpty: getTableAttr('data-hide-if-empty'),
                onlyExportVisibleColumns:
                    getTableAttr('data-only-export-visible-columns') === 'true',
                suppressLabelColumn: getTableAttr('data-suppress-label-column')
            };

        let pageLength = getTableAttr('data-page-length');

        if (pageLength) {
            initialStateConfig.tableOptions.pageLength = parseInt(pageLength);
        }

        // get the request params required for the service call
        initialStateConfig.dataParams = dtUtils.buildRequestParams('data', initialStateConfig);
        initialStateConfig.colParams = dtUtils.buildRequestParams('columns', initialStateConfig);
        initialStateConfig.fieldParams = dtUtils.buildRequestParams('fields', initialStateConfig);

        let editor = undefined;
        if (initialStateConfig.isEditable) {
            editor = new $.fn.dataTable.Editor({});
        }

        initialStateConfig.tableOptions.buttons = this.defaultAddButtons(
            initialStateConfig,
            this,
            editor
        );

        let currentProps = this.props;

        //default created row functionality
        initialStateConfig.tableOptions = {
            ...initialStateConfig.tableOptions,
            createdRow: function(row, data, index) {
                //if createdRow function is being passed in from HOC, call the function
                if (currentProps.createdRow) {
                    currentProps.createdRow(row, data, index);
                }
            }
        };

        //if we have buttons to display, or the filter is enabled - we need a row in the table header to put these things in
        if (initialStateConfig.tableOptions.buttons.length > 0 || initialStateConfig.hasFilter) {
            if (pageLength == 10) {
                //if limiting results to 10 it is a small gadget and should have filter and buttons on same row (if it has a filter)
                initialStateConfig.tableOptions = {
                    ...initialStateConfig.tableOptions,
                    dom: dtConfig.tableWithToolbarConfig
                };
            } else {
                initialStateConfig.tableOptions = {
                    ...initialStateConfig.tableOptions,
                    dom: dtConfig.tableWithToolbarAndLength
                };
            }
        } else {
            //if there is nothing to display on the table header (buttons or filter or search, then don't define the header)
            initialStateConfig.tableOptions = {
                ...initialStateConfig.tableOptions,
                dom: dtConfig.simpleTableConfig
            };
        }

        //if we want the filter box to be visible
        if (initialStateConfig.hasFilter === true) {
            initialStateConfig.tableOptions = {
                ...initialStateConfig.tableOptions,
                bFilter: true
            };
        }

        if (initialStateConfig.hasScrollCollapse) {
            initialStateConfig.tableOptions = {
                ...initialStateConfig.tableOptions,
                ...dtConfig.verticalScrollConfig
            };
        }

        if (initialStateConfig.hasMultiSelect === 'false') {
            initialStateConfig.tableOptions = {
                ...initialStateConfig.tableOptions,
                select: {
                    style: 'single'
                }
            };
        }


        // store this so future calls to updateComponentState() don't lose the initial configuration
        this.initialStateConfig = initialStateConfig;

        this.loadComponentData(initialStateConfig);
    }

    // tells whether an update is necessary (check if the data has actually changed)
    shouldComponentUpdate(nextProps, nextState) {
        let freeTextChanged = this.state.dataParams.freeText !== nextState.dataParams.freeText,
            facetFiltersChanged =
                this.state.dataParams.facetFilters !== nextState.dataParams.facetFilters,
            searchGraphChanged = this.state.searchGraph !== nextState.searchGraph,
            columnsServiceChanged = this.state.columnsService !== nextState.columnsService,
            dataServiceChanged = this.state.dataService !== nextState.dataService,
            dataChanged = this.state.tableOptions.data !== nextState.tableOptions.data;

        // this.hardBuildRequired = (searchGraphChanged || columnsServiceChanged);
        this.hardBuildRequired = true;

        return (
            freeTextChanged ||
            facetFiltersChanged ||
            searchGraphChanged ||
            columnsServiceChanged ||
            dataServiceChanged ||
            dataChanged
        );
    }

    componentWillUpdate(nextProps, nextState) {
        if (nextState.successfullyResolved) {
            this.buildDataTable(nextState);
        }
    }

    initFixedHeader() {
        let header_config = {},
            content_container = this.$tableContainer.parents('.ui-layout-content');

        if (content_container) {
            header_config.headerOffset = content_container.offset().top;
        }

        new $.fn.dataTable.FixedHeader(this.dataTablesInstance, header_config);

        if (content_container) {
            content_container.off('scroll').on('scroll', () => {
                if (this.dataTablesInstance && this.dataTablesInstance.fixedHeader) {
                    this.dataTablesInstance.fixedHeader.adjust();
                }
            });
        }
    }

    cleanupFixedHeader() {
        let content_container = this.$tableContainer.parents('.ui-layout-content');

        if (content_container) {
            content_container.off('scroll');
        }
    }

    buildDataTable(nextState) {
        if (this.hardBuildRequired) {
            if (this.dataTablesInstance) {
                this.dataTablesInstance.destroy();
            }

            this.dataTablesInstance = this.$tableContainer
                .find('table')
                .DataTable(nextState.tableOptions);

            if (this.initialStateConfig.hasFixedHeader === 'true') {
                this.initFixedHeader();
            }

            /* on selection of a row */
            this.dataTablesInstance.on('select', (e, dt, type, indexes) => {
                this.defaultOnSelect(e, dt, type, indexes);
            });

            /* on double click of a row */
            this.dataTablesInstance.on('dblclick', (e, dt, type, indexes) => {
                this.defaultOnDoubleClick(e, dt, type, indexes);
            });

            this.$tableContainer.find('.dt-buttons.btn-group').addClass('btn-group-sm');
            this.$tableContainer
                .find('.viewResourceBtn')
                .removeClass('btn-default')
                .addClass('btn-primary');
        } else {
            this.dataTablesInstance.clear();
            this.dataTablesInstance.rows.add(nextState.tableOptions.data).draw();
        }

        // re-select any previously selected row
        if (this.state.curRow) {
            this.dataTablesInstance.row(`[id="${this.state.curRow}"]`).select();
        }
    }

    updateComponentState() {

        if(Object.keys(this.state.dataParams).length === 0){
            //table was destroyed and rebuilt, this component doesn't exist anymore
            return;
        }

        let freeTextChanged = this.state.dataParams.freeText !== this.store.getState().freeText,
            facetFiltersChanged =
                this.state.dataParams.facetFilters !== this.store.getState().searchFacets;

        if(freeTextChanged || facetFiltersChanged){
            var updateStateRequest = true;
            if (this.lastServiceRequests) {
                this.lastServiceRequests[0].abort();
                this.lastServiceRequests[1].abort();

                //make updateStateRequest a promise
                updateStateRequest = this.setState({
                    ...this.initialStateConfig,
                    successfullyResolved: false
                });
            }

            Promise.resolve(updateStateRequest).then(
                () => {
                    let curDataParams = dtUtils.buildRequestParams('data', this.state);
                    let curColParams = dtUtils.buildRequestParams('columns', this.state);

                    // merge new params with old state obj
                    var newStateConfig = {
                        ...this.initialStateConfig,
                        ...this.state,
                        dataParams: curDataParams,
                        colParams: curColParams
                    };

                    this.loadComponentData(newStateConfig);
                },
                err => {
                    console.warn(err);
                }
            );
        }
            return;
    }

    reflowTable() {
        this.dataTablesInstance.columns.adjust();
        this.dataTablesInstance.responsive.resize();
    }

    defaultOnDoubleClick(e, dt, type, indexes) {
        //no default action currently

        //if custom datatable passes in double click event, bind it
        if (this.props.onDoubleClick) {
            this.props.onDoubleClick(e, dt, type, indexes);
        }
    }

    defaultOnSelect(e, dt, type, indexes) {
        let uri = dt.row(indexes).data().uri;
        this.setState({ curRow: uri });

        //if resource selected event exists, fire
        if (this.state.resourceSelectedEvent) {
            gadgets.Hub.publish(this.state.resourceSelectedEvent, uri);
        }

        //if this is a custom datatable that has a custom onSelect method
        if (this.props.onSelect) {
            this.props.onSelect(e, dt, type, indexes);
        }
    }

    defaultAddButtons(state, context, editor) {
        //create empty button array
        let buttons = [];

        //if editable datatable
        if (state.isEditable) {
            buttons = buttons.concat(dtEditorButtons.addButtons(state, editor, context));
        }

        if (this.props.addButtons) {
            buttons = buttons.concat(this.props.addButtons(state, context, editor));
        }

        if (state.hasSelectAll) {
            buttons = buttons.concat(dtConfig.selectAllConfig);
        }

        if (state.hasExports) {
            buttons = buttons.concat(dtConfig.exportColumnConfig(state));
        }

        //if search datatable
        if (state.hasViewDetails) {
            buttons = buttons.concat(dtEditorButtons.detailsbutton(state, context, editor));
        }

        return buttons;
    }

    loadBothFromEndpoint(stateConfig) {
        let requestsArray = [],
            dataRequest = utils.getDataForEndpoint(stateConfig.dataParams),
            columnsRequest = utils.getDataForEndpoint(stateConfig.colParams);

        this.loadingMode(true);

        requestsArray.push(dataRequest, columnsRequest);

        this.lastServiceRequests = requestsArray;

        // TODO: only call this once if we can get away with it
        // if (stateConfig.isEditable) {
        //     requestsArray.push(fieldsRequest);
        // }

        // wait for all the data requests to be returned
        Promise.all(requestsArray)
            .then(
                data => {

                    // if checkbox selection is enabled for this table
                    let cbSelectionCapability = false; // could later make this dynamic with stateConfig.hasCheckboxSelection
                    let columnsDefinition = dtConfig.buildColumnsData(
                        data[1],
                        cbSelectionCapability
                    );

                    // merge the new data into the initial state config obj
                    stateConfig = {
                        ...stateConfig,
                        tableOptions: {
                            ...stateConfig.tableOptions,
                            data: data[0].data,
                            columns: columnsDefinition
                        },
                        successfullyResolved: true
                    };

                    if (data[0] && data[0].maxTableRows && data[0].totalTableRows) {
                        stateConfig.tableOptions.infoCallback = dtUtils.infoCallbackFunc(
                            data[0].maxTableRows,
                            data[0].totalTableRows
                        );
                    }

                    // update the index's
                    if (this.state.tableOptions.aaData && this.state.tableOptions.aoColumns) {
                        stateConfig.tableOptions.aaData = data[0].data;
                        stateConfig.tableOptions.aoColumns = data[1];
                    }

                    //if we have an onload function that we want to have fire after the data is loaded into the state object
                    if (this.props.onLoad) {
                        stateConfig = this.props.onLoad(stateConfig);
                    }
                    this.setState(stateConfig);

                    this.loadingMode(false);
                },
                () => {
                    this.setState({
                        ...this.initialStateConfig,
                        successfullyResolved: false
                    });
                }
            )
            .then(() => {
                this.lastServiceRequests = null;
            });
    }

    loadBothFromDom(stateConfig) {
        this.loadingMode(true);

        stateConfig = {
            ...stateConfig,
            tableOptions: {
                ...stateConfig.tableOptions,
                data: JSON.parse(stateConfig.dataData),
                columns: JSON.parse(stateConfig.columnData)
            },
            successfullyResolved: true
        };

        this.setState(stateConfig);

        this.loadingMode(false);
    }

    loadComponentData(stateConfig) {
        if (stateConfig.fromDom === 'true') {
            this.loadBothFromDom(stateConfig);
        } else {
            this.loadBothFromEndpoint(stateConfig);
        }
    }

    loadingMode(mode) {
        if (mode === true) {
            this.$tableContainer.prepend(
                '<div class="cp-preloader cp-preloader_absolute"><div class="cp-preloader__ball"></div></div>'
            );
        } else {
            this.$tableContainer.find('.cp-preloader').remove();
        }
    }

    componentWillUnmount() {
        if (this.dataTablesInstance) {
            this.dataTablesInstance
                .destroy(true)
                .clear()
                .draw();
            this.dataTablesInstance = null;
            this.cleanupFixedHeader();
            this.unsubscribe();
        }
    }

    render() {
        if (this.state.hideIfEmpty === true || this.state.hideIfEmpty !== undefined) {
            var dataLength;
            if (this.state.tableOptions.data !== undefined) {
                dataLength = this.state.tableOptions.data.length;

                if (dataLength === 0) {
                    $(this.props.domReference)
                        .next()
                        .removeClass('ui-helper-hidden-accessible');
                    $(this.props.domReference).addClass('ui-helper-hidden-accessible');
                }
            }
        }

        return (
            <div id={`${this.props.domReference.id}-container`}>
                <table
                    className="table table-striped table-bordered hover table-condensed"
                    width="100%"
                />
            </div>
        );
    }
}

export default DataTableComponent;



