import 'core-js/fn/object/assign';

import React from 'react';
import ReactDOM from 'react-dom';
import PropTypes from 'prop-types';
import {
    VictoryChart,
    VictoryAxis,
    VictoryBar,
    VictoryContainer,
    VictoryLabel,
    VictoryLegend,
    VictoryStack,
    VictoryTheme,
    VictoryTooltip,
    VictoryZoomContainer
} from 'victory';
import * as chartUtil from './chartUtil';
import TopBraidLoading from '../loading';
import Message from '../message';

class CustomAxisLabel extends React.Component {
    render() {

        var _props = {
            ...this.props,
            datum: {
                x: this.props.datum,
                y: 0
            }
        };

        return (<g>
            <VictoryLabel {...this.props}
                         text={truncateWord(this.props.text)} style={{fontSize: 12}}/>
            <VictoryTooltip {..._props}
                            orientation={'top'}
                            style={{fontSize: 14}}
                            text={reflowWord(_props.text)}/>
        </g>);
    }
}

CustomAxisLabel.defaultEvents = VictoryTooltip.defaultEvents;
CustomAxisLabel.propTypes = {
    toolTipText: PropTypes.oneOfType([PropTypes.string, PropTypes.number, PropTypes.func, PropTypes.array])
};

const getZoomLimit = () => {

}

const getStaticContainer = () => {
   return <VictoryContainer responsive={false}/>;
}

const getZoomContainer = (zoom_limit) => {
    console.log(zoom_limit);
   return <VictoryZoomContainer className="VictoryContainer VictoryZoomContainer"
                                               zoomDomain={{ x: [0, zoom_limit] }}
                                               zoomDimension="x"
                                               responsive={false}
                                               allowZoom={false}
                                               allowPan={true}/>;

}



const reflowWord = (word, size) => {
  size = size | 200;
  var lines =  chartUtil.getLines(chartUtil.wordsWidth(word), size, {fontSize: 12});

  return lines.join('\n')
}

const truncateWord = (word) => {

    if (word && word.length > 0) {
        var lines = chartUtil.getLines(chartUtil.wordsWidth(word), 100, {fontSize: 12});
        if (lines.length > 2) {
            lines.length = 2;
            lines.push('...');
        }
        return lines.join('\n');
    }

    return word;
}

class TopBraidStackChart extends React.Component {

    constructor(props) {
        super(props);
        this.$container = $(this.props.domReference);
        this.getAttr = chartUtil.getElementAttr(this.$container);
        this.state = {
            data: undefined,
            zoom_limit: (this.getChartWidth() > 500 ? 10 : 5)
        };
    }

    getChartWidth() {
        return this.getAttr('data-width') | 500;
    }

    getChartHeight() {
        return this.getAttr('data-height') | 350;
    }

    componentDidMount() {

        var dataService = this.getAttr('data-endpoint'),
            subjectArea = this.getAttr('data-subjectArea');

        if (dataService != null) {
            var requestData = {
                _viewClass: dataService,
                subjectArea: subjectArea
            }

            var jqXHR = chartUtil.getDataFromService(requestData);

            jqXHR.then((data) => {
                this.setState({data: data});
            }, (err) => {});
        }
    }

    render() {
        if (!this.state.data) {
            return (<TopBraidLoading/>)
        };

        if (this.state.data.hasOwnProperty('message')) {
            return (<Message value={this.state.data.message}/>)
        }

        let bars = [];

        for (var i in this.state.data.bars) {
            bars.push(<VictoryBar labelComponent={<VictoryTooltip/>}
                                  data={this.state.data.bars[i]}
                                  style={{data: {width: 35}}}
                                  x="status"
                                  y="count"
                                  key={i}/>)
        }

        return (
          <VictoryChart width={this.getChartWidth()} height={this.getChartHeight()}
            domainPadding={{
                x: 40,
                y: [40, 80]
            }}
            theme={VictoryTheme.material}
            containerComponent={ (this.state.data.axis.values.length > this.state.zoom_limit ? getZoomContainer(this.state.zoom_limit) : getStaticContainer()) }>

            {this.state.data.axis.values.length > this.state.zoom_limit && <VictoryLabel style={{ fontSize: 16,fontColor: 'red' }}
                                                                              x={this.getChartWidth() - 125}
                                                                              y={40}
                                                                              text="Chart pans &#8592; &#8594;"/> }

            <VictoryLegend x={60} orientation="horizontal" itemsPerRow={4} style={{
                    border: {
                        stroke: "black"
                    },
                    labels: {
                        fontSize: 12
                    }
                }} data={this.state.data.legend}/>
            <VictoryAxis tickValues={this.state.data.axis.values}
                         tickFormat={(tick) => `${this.state.data.axis.format[tick - 1]}`}
                         tickLabelComponent={<CustomAxisLabel  />}
                         events={[{
                                target: "tickLabels",
                                eventHandlers: {
                                    onMouseOver: () => {
                                        return [
                                            {
                                                mutation: () => ({active: true})
                                            }
                                        ];
                                    },
                                    onMouseOut: () => {
                                        return [
                                            {
                                                mutation: () => ({active: false})
                                            }
                                        ];
                                    }
                                }
                            }
                         ]}
                         style={{ tickLabels: {paddingLeft: 10,paddingRight: 10} }}/>
            <VictoryAxis dependentAxis={true}
                         tickFormat={(x) => (`${x}`)}/>
            <VictoryStack >
                {bars}
            </VictoryStack>
        </VictoryChart>
      )
    }
}

export default TopBraidStackChart;



