/*global swa:true, gadgets*/
/*eslint no-undef: "error"*/
/*eslint no-console: ["error", { allow: ["warn", "error", "log"] }] */
'use strict';

import $ from 'jquery';
import store from '../redux/store';

$(document).ready(() => {

    let isPageWithFacetsTree = $('.facets-tree').length > 0;

    if (isPageWithFacetsTree) {

        // store these values so we can check if the data has actually changed
        // and not make updates which are not needed
        swa.dataStore.lastFacetFilterStr = undefined;
        swa.dataStore.lastFreeText = undefined;

        // listen for facet additions
        $('.facets-tree').on('click', '.swa-facets-selectable.fas-facet[data-property]', function () {

            let $facet = $(this),
                selectedFacet = $facet.attr('data-property'),
                label = $facet.text();

            swa.dispatch(swa.actions.addSearchFacet({selectedFacet, label}));
        });

        //hides empty facet result containers
        gadgets.Hub.subscribe('teamwork.facets.loaded',function(event, treeContainerId){
            $('#' + treeContainerId).find('[data-empty-facet]').parents('.facet-container').hide();
        });


        store.subscribe(() => {

            let treeContainerId = $('.facets-tree > [uistate]').attr('id'),
                loadObj = {},
                facetFilterStr = store.getState().searchFacets.map((facet) => {
                    return facet.selectedFacet;
                }).join('^|');


            // if there are any facetFilters represented in app state
            if (facetFilterStr) {
                // capture it and inform the server via swa.load (first two params)
                loadObj.facetFilters = JSON.stringify(facetFilterStr);
            }

            // if there is a freeText term represented in app state
            if (store.getState().textSearch) {
                // capture it and inform the server via swa.load (first two params)
                loadObj.freeText = JSON.stringify(store.getState().textSearch);
            }

            // only update when something this widget cares about has changed
            if (loadObj.freeText !== swa.dataStore.lastFreeText || loadObj.facetFilters !== swa.dataStore.lastFacetFilterStr) {
                let $jqXHR = swa.load(treeContainerId, loadObj);

                Promise.resolve($jqXHR)
                    .then(() => {
                        swa.dataStore.lastFreeText = loadObj.freeText;
                        swa.dataStore.lastFacetFilterStr = loadObj.facetFilters;
                    }, (err) => {
                        console.warn(err);}
                    );
            }

        });

    }

});



