/*global swa:true, teamwork */
import $ from 'jquery';

'use strict';

//gets the resource information
export const getResourceInfo = () => {
    var typeLabel = null;
    var resourceType = null;

    if($('#type-select')[0].length > 0){
        resourceType = $('#type-select')[0].value;
        typeLabel = $('#type-select')[0].options[$('#type-select')[0].options.selectedIndex].innerHTML;
    }
    else{
        resourceType = $('#type-select').val();
        typeLabel = $('#type-select').data('ref');
    }

    if(resourceType.indexOf('-') == 0) {
        resourceType = resourceType.substring(1);
    }

    return {typeLabel, resourceType};
};

/**
 * This iterates over the rows in a data table and
 * returns any that have been selected.
 * @param dt the datatable
 * @return an array of selected rows.
 */
export const getSelectedRows = (dt) => {
    return dt.rows({selected:true}).data().map((selectedRow) => {
        return selectedRow;
    });
};

/**
 * This iterates over the selected rows in a data table and
 * returns the URI attrivute for each row.
 * @param selectedItems the selected rows.
 * @return an array of URI attributes.
 */
export const getSelectedURIs = (selectedItems) => {
    return selectedItems.map((elem) => {
        return elem['uri'];
    });
};

export const infoCallbackFunc = (maxTableRows, totalRecordRows) => {

    return function(settings, start, end, max, total, pre) {
        if (totalRecordRows >= maxTableRows) {
            return `<div>Showing ${start} to ${end} of ${total} entries
            <span class="table-information" title="This result set has reached the maximum allowed rows of ${maxTableRows}.  Including the current result set there are ${totalRecordRows} rows available.  Please utilize the search form to further reduce the result set.">
               <i aria-hidden="true" class="fa fa-exclamation-triangle"/>
            </span></div>`;
        } else {
            return pre;
        }
    };
};

// builds a params obj using properties in both redux and local component state
export const buildRequestParams = (type, state) => {

    let queryParams = {};

    switch (type) {
    // you're requesting table DATA
    case 'data':

        // the primary web service
        queryParams._viewClass = state.dataService;

        // used in the editor application (instances grid)
        if (state.searchGraph) {
            queryParams.searchGraph = state.searchGraph;
        }

        // needed for comparison matrix
        if (state.limit) {
            queryParams.limit = state.limit;
        }

        // used in SearchPage
        if (swa.getAppState().textSearch) {
            queryParams.freeText = swa.getAppState().textSearch;
        }

        // used in SearchPage
        if (swa.getAppState().searchFacets.length > 0) {
            let facetString = swa.getAppState().searchFacets.map(facet => facet.selectedFacet).join('^|');
            queryParams.facetFilters = facetString;
        }

        break;
    // you're requesting table COLUMNS
    case 'columns':

        queryParams._viewClass = state.columnsService;


        if(state.suppressLabelColumn){
            queryParams.suppressLabelColumn = 'true';
        }


        if (swa.queryGraphURI) {
            queryParams.queryGraph = swa.queryGraphURI;
        }

        // used in the editor application (instances grid)
        if (state.searchGraph) {
            queryParams.searchGraph = state.searchGraph;
        }

        break;
    case 'fields':

        var resource = state.resourceType;
        queryParams._viewClass = state.createService;
        queryParams.resourceType = resource;
        // queryParams._base = swa.queryGraphURI;

        break;

    default:

        // debug
        queryParams.missingType = true;
    }

    // need for making this generic?
    // includeBase as a truthy isn't enough
    // because swa.queryGraphURI is not always a set global
    // better to pass it explicitly and use swa.queryGraphURI as a fallback
    if (state.cmBaseGraph) {
        queryParams._base = state.cmBaseGraph;
    }

    if (!queryParams._base && swa.queryGraphURI) {
        queryParams._base = swa.queryGraphURI;
    }

    if (state.queryParam && state.queryParamValues) {
        queryParams[state.queryParam] = state.queryParamValues;
    }

    // standard for all web service calls
    queryParams._snippet = true;

    return queryParams;
};



