/*global document, console, jQuery, swa, carousel, htmlTemplateRenderer, dataTable */
//(function ($) {
import carousel from './carousel';
import htmlTemplateRenderer from './htmlTemplateRenderer';

'use strict';

var requestArray = [],
    WIDGET_ATTR_NAME = 'data-swa-widget',
    ENDPOINT_ATTR_NAME = 'data-widget-endpoint',
    TYPE_ATTR_NAME = 'data-widget-type',
    WIDGET_TYPES = {
        'swa.carousel': carousel,
        'swa.htmlTemplate': htmlTemplateRenderer
    };

/**
 * Shorthand for getting various attribute values for a given element
 * @return {function}
 */
function getElementAttribute (element) {
    return function (attr) {
        return element.attr(attr);
    };
}

/**
 * Notifies the UI if the value supplied for TYPE_ATTR_NAME on a widget doesn't correspond to
 * a pre-built widget handler that's already defined. To register a custom widget handler, define
 * a global object on the page and make it available by adding to the WIDGET_TYPES map above.
 * @param {object} state - an object representing the UI widget's "state". Contains various data
 * related to the widget.
 */
function handleWidgetTypeNotSupported (state) {
    var $widget = state.$widget;

    $widget
        .addClass('error')
        .html('<h4>Widget type <strong>' + state.widgetType + '</strong> not supported</h4>' +
                '<p>' + JSON.stringify(state.data) + '</p>');
}

/**
 * Notifies the UI of a problematic/missing required attribute for a given widget
 * @param {string} attribute - the problematic attribute
 * @param {object} $widget - the jQuery wrapped DOM element we're trying to initialise the widget on
 */
function handleValidationError (attribute, $widget) {
    $widget
        .addClass('error')
        .html('There was a problem with attribute: <strong>' + attribute + '</strong>');
}

/**
 * Determines if a string has a value
 * @param {string} string - the value to test
 * @todo trim this string variable when checking for empty string
 * @return {boolean}
 */
function hasValue (string) {
    return string !== null && string !== 'undefined' && string !== '';
}

/**
 * Determines if a value is of type string
 * @param {string} string - the value to test
 * @return {boolean}
 */
function isString (string) {
    return hasValue(string) && typeof string === 'string';
}

/**
 * Determines if a value is a function
 * @param {mixed} possibleFunction - the value to test
 * @return {boolean}
 */
function isFunc (possibleFunction) {
    return hasValue(possibleFunction) && typeof possibleFunction === 'function';
}

/**
 * Crawls the DOM looking for the "data-swa-widget" attribute.
 * Initialise each of these elements as what we'll call an "SWA Widget"
 * SWA Widgets have three required attributes.
 * @example <div data-swa-widget="" data-widget-endpoint="" data-widget-type="">
 * These three attribute values dictate how the widget is initialized and looked after
 * @param "data-swa-widget" Used for development/debugging purposes, names the component.
 * @param "data-widget-endpoint" The API service endpoint that fetches the required data for the widget.
 * @param "data-widget-type" dictates what js function runs to handle initialisation and event bindings.
 * Possible values for a widget type are currently swa.carousel and swa.htmlTemplate.
 * @todo define an SWP component that generates these necessary DOM parts automatically
 * @example <teamwork:Widget arg:dataSwaWidget="" arg:dataWidgetEndpoint="" arg:dataWidgetType=""/>
 * @returns requestArray {Array} stack of jqXHR objects, can be used to do an action
 * after ALL widget ajax requests have been fulfilled
 */
function init () {
    $('[' + WIDGET_ATTR_NAME + ']').each(function (index, element) {

        var $widget = $(element),
            getWidgetAttr = getElementAttribute($widget),
            jqXHR,
            actor;

        // ensure an endpoint is supplied for the widget
        if (!isString(getWidgetAttr(ENDPOINT_ATTR_NAME))) {
            handleValidationError(ENDPOINT_ATTR_NAME, $widget);
            return true;
        }

        // ensure the widget has a type we can attempt to work with
        if (!isString(getWidgetAttr(TYPE_ATTR_NAME))) {
            handleValidationError(TYPE_ATTR_NAME, $widget);
            return true;
        }

        $widget.html('<div class="cp-preloader cp-preloader"><div class="cp-preloader__ball"></div></div>');

        jqXHR = swa.dataStore.getDataForEndpoint(getWidgetAttr(ENDPOINT_ATTR_NAME));

        requestArray.push(jqXHR);

        // once the request is fulfilled..
        $.when(jqXHR)
            .fail(function (jqXHR, textStatus, errorThrown) {
                $widget
                    .addClass('error')
                    .html('Status: <strong>' + textStatus + '</strong><br>Error Thrown: <strong>' + errorThrown + '</strong>');

                console.error('Problem getting data for widget: ' + getWidgetAttr(WIDGET_ATTR_NAME));

            }).done(function (data, textStatus, jqXHR) {

                var state = {
                    $widget: $widget,
                    widgetType: getWidgetAttr(TYPE_ATTR_NAME),
                    data: data,
                    textStatus: textStatus,
                    jqXHR: jqXHR
                };

                actor = WIDGET_TYPES[state.widgetType];

                if (actor) {
                    // "render" is the public method that each widget module exposes
                    actor.render(state);

                    /**
                     * Subscribe the (each) widget to a custom event "widgetUpdate"
                     * "widgetUpdate" is the event topic we'll broadcast to communicate with other widgets
                     * Each widget choses which widget types it will react to when this event is broadcasted in the update function
                     * @example $('[data-swa-widget]').trigger('widgetUpdate', 'swa.search');
                     * @param {object} event - standard jQuery event object
                     * @param {string} updatedWidgetType - the type of the widget e.g. swa.carousel, swa.htmlTemplate
                     */
                    $widget.on('widgetUpdate', null, actor, function (event, updatedWidgetType) {

                        // console.log("Passed in data from trigger: " + updatedWidgetType);
                        if (isFunc(event.data.update)) {
                            // update method should accept the updatedWidgetType
                            // as a param to see if the update is something the widget
                            // cares about
                            // makes the $widget available via $(this) in all the
                            // individual ui components
                            event.data.update.call($widget, updatedWidgetType);
                        }
                    });
                } else {
                    handleWidgetTypeNotSupported(state);
                }


            });


    });

    return requestArray;

}

$(document).ready(function () {

    // start the engine
    var widgetRequests = init();

    // when ALL the requests have been fulfilled...
    // $.when.apply(null, widgetRequests)
    //     .fail(function (jqXHR, textStatus, errorThrown) {
    //         console.error('There was a problem with one of the widgets: ', errorThrown);
    //     })
    //     .done(function (data, textStatus, jqXHR) {
    //         console.log('widgets initialized');
    //     });
});

