/*global jQuery:true*/
(function($) {

    function bindNeighborGramClick() {
        $('.details-action-neighborgram').on('click', function() {
            var $this = $(this),
                link = $this.attr('data-link');

            window.open(link, '_blank');
        });
    }

    $(document).ready(function() {
        bindNeighborGramClick();
    });

})(jQuery);



