'use strict';

import * as actionTypes from './actions-constants';
import { combineReducers } from 'redux';

function advancedSearchReducer(state = false, action) {
    if (action.type === actionTypes.ADVANCED_SEARCH_TOGGLED) {
        return action.payload;
    }
    return state;
}

function primaryNavReducer(state = true, action) {
    if (action.type === actionTypes.PRIMARY_NAV_TOGGLED) {
        return action.payload === 'isOpen' ? true : false;
    }
    return state;
}

function languagesReducer(state = [], action) {
    if (action.type === actionTypes.SET_LANGUAGES) {
        return action.payload;
    }

    return state;
}

/**
 * Returns a state object that represents selected search facets (facetFilters)
 *
 * @param state Array  A collection of selected facets
 * @param action  Object  The incoming action - ex: {selectedFacet, label}
 * @return state
 */
function searchFacetsReducer(state = [], action) {
    // if we are adding
    if (action.type === actionTypes.ADD_SEARCH_FACET) {
        let existingFacet = state.filter(
            facet => facet.selectedFacet === action.payload.selectedFacet
        )[0];

        // console.log(state.concat(action.payload));

        // if this facet already existed within the state obj, return that existing state obj
        // otherwise add the new facet to the state and return that
        return existingFacet ? state : state.concat(action.payload);
    }

    // if we are removing a single facet
    if (action.type === actionTypes.REMOVE_SEARCH_FACET) {
        return state.filter(facet => facet.selectedFacet !== action.payload);
    }

    // if we are removing all the searchFacets
    if (action.type === actionTypes.REMOVE_ALL_SEARCH_FACETS) {
        return state.filter(() => false);
    }

    if (action.type === actionTypes.APPLY_SEARCH_STATE) {
        // must return an object structure that contains a label and selectedFacet property!!
        if (action.payload.selectedFacets) {
            return action.payload.selectedFacets.map(facet => {
                return {
                    label: facet.label,
                    selectedFacet: facet.selectedFacet
                };
            });
        }
    }

    return state;
}

/**
 * Returns a state object that represents search facet filter (freeText)
 *
 * @param state String  A search string
 * @param action  Object  The incoming action - ex: 'some search string'
 * @return state
 */
function textSearchReducer(state = '', action) {
    if (action.type === actionTypes.ADD_TEXT_SEARCH) {
        return action.payload;
    } else if (action.type === actionTypes.REMOVE_TEXT_SEARCH) {
        return '';
    } else if (action.type === actionTypes.REMOVE_ALL_SEARCH_FACETS) {
        // textSearch is a type of search facet
        return '';
    } else if (action.type === actionTypes.REMOVE_SEARCH_FILTERS) {
        return '';
    } else if (action.type === actionTypes.APPLY_SEARCH_STATE) {
        if (action.payload.textSearch.length === 0) { //if textSearch is blank, we are resetting the state and need to clear out any existing value
            return "";
        }
        else if(action.payload.textSearch){
            return action.payload.textSearch;
        }
    }

    return state;
}

/**
 * Returns a state object that represents the active resource
 *
 * @param state String  A search string
 * @param action  Object  The incoming action - ex: 'someUri'
 * @return state
 */
function resourceChangedReducer(state = '', action) {
    if (action.type === actionTypes.RESOURCE_CHANGED) {
        return action.payload;
    }

    return state;
}

function resourceTypeChangedReducer(state = {}, action) {
    if (action.type === actionTypes.RESOURCE_TYPE_CHANGED) {
        return action.payload;
    } else if (action.type === actionTypes.APPLY_SEARCH_STATE) {
        if (action.payload.selectedResourceType) {
            return action.payload.selectedResourceType;
        }
    }

    return state;
}

function resourceTypeFieldsReducer(state = [], action) {
    if (action.type === actionTypes.SET_RESOURCE_FIELDS) {
        return action.payload;
    }

    return state;
}

const findFilterParent = (state, payload) => {
    let _payload = {},
        path = payload.path.split('.');

    if (path.length > 1) {
        path.pop();
    }

    if (path.length > 1) {
        _payload.path = path.join('.');
    } else {
        _payload.path = path[0];
    }

    return findFilter(state, { ...payload, ..._payload });
};

const findFilter = (state, payload) => {
    let lastKnownFilter,
        matchFilter,
        path = payload.path.split('.');

    let filterList = state;

    path.forEach(segment => {
        if (filterList) {
            matchFilter = filterList.filter(filter => {
                return filter.name === segment ? filter : false;
            })[0];

            if (matchFilter != null) {
                lastKnownFilter = matchFilter;

                if (matchFilter.value) {
                    filterList = matchFilter.value;
                }
            }
        }
    });

    return lastKnownFilter;
};

function searchFiltersReducer(state = [], action) {
    if (action.type == actionTypes.ADD_SEARCH_FILTER) {
        let filter = findFilter(state, action.payload);

        if (!filter) {
            return state.concat(action.payload);
        } else {
            if (action.payload.path.indexOf('.') !== -1) {
                let filter = findFilter(state, action.payload);
                if (filter.value && filter.value.length > 0) {
                    filter.value = filter.value.concat(action.payload);
                } else {
                    filter.value = [action.payload];
                }
            }
        }

        return state;
    } else if (action.type === actionTypes.UPDATE_SEARCH_FILTER) {
        let filter = findFilter(state, action.payload);

        if (filter) {
            filter.value = action.payload.value;
        } else {
            console.warn('filter was undefined', action.payload.value);
        }
    } else if (action.type === actionTypes.UPDATE_SEARCH_FILTER_ACTION) {
        let filter = findFilter(state, action.payload);

        filter.action = action.payload.value;
    } else if (action.type === actionTypes.UPDATE_SEARCH_FILTER_LANG) {
        let filter = findFilter(state, action.payload);

        filter.lang = action.payload.value;
    } else if (action.type === actionTypes.APPLY_SEARCH_STATE) {
        if (action.payload.searchFilters) {
            return action.payload.searchFilters;
        }
    } else if (action.type === actionTypes.REMOVE_SEARCH_FILTER) {
        let _list = state;
        if (action.payload.path.indexOf('.') !== -1) {
            let targetFilter = findFilterParent(state, action.payload);
            let _list = targetFilter.value;

            if (_list) {
                targetFilter.value = _list.filter(filter => filter.name !== action.payload.name);
            }

            return state;
        }

        return state.filter(filter => filter.name !== action.payload.name);
    } else if (action.type === actionTypes.RESOURCE_TYPE_CHANGED) {
        state = [];
    } else if (action.type === actionTypes.REMOVE_SEARCH_FILTERS) {
        state = [];
    }

    return state;
}

function searchColumnsReducer(state = [], action) {
    if (action.type == actionTypes.ADD_SEARCH_COLUMN) {
        let existingColumn = state.filter(column => column.path === action.payload.path)[0];

        return existingColumn ? state : state.concat(action.payload);
    } else if (action.type === actionTypes.REMOVE_SEARCH_COLUMN) {
        return state.filter(column => column.path !== action.payload.path);
    } else if (action.type === actionTypes.APPLY_SEARCH_STATE) {
        if (action.payload.searchColumns) {
            return action.payload.searchColumns;
        }
    } else if (action.type === actionTypes.RESOURCE_TYPE_CHANGED) {
        state = [];
    } else if (action.type === actionTypes.REMOVE_SEARCH_COLUMNS_AT_PATH) {
        if(state && state.length > 0){
            return state.filter(column => !column.path.startsWith(action.payload.path));
        }
    }
     else if (action.type === actionTypes.REMOVE_SEARCH_COLUMNS) {
        state = [];
    }

    return state;
}

function searchRequestReducer(state = 0, action) {
    if (action.type === actionTypes.SEARCH_REQUEST) {
        return action.payload;
    }

    return state;
}

/**
 * Returns a state object that represents the searchGraph
 *
 * @param state String  A uri
 * @param action  Object  The incoming action - ex: 'some search string'
 * @return state
 */
// function searchGraphReducer(state = '', action) {
//     if (action.type === actionTypes.UPDATE_SEARCH_GRAPH) {
//         return action.payload;
//     }

//     return state;
// }

export const reducers = combineReducers({
    advancedSearch: advancedSearchReducer,
    primaryNav: primaryNavReducer,
    languages: languagesReducer,
    searchFacets: searchFacetsReducer,
    textSearch: textSearchReducer,
    selectedResource: resourceChangedReducer,
    selectedResourceType: resourceTypeChangedReducer,
    resourceTypeFields: resourceTypeFieldsReducer,
    searchFilters: searchFiltersReducer,
    searchColumns: searchColumnsReducer,
    searchRequest: searchRequestReducer,
    searchFilters: searchFiltersReducer
});



