/*global swa:true, teamwork */
import 'url-search-params-polyfill';
import $ from 'jquery';
import * as utils from './Utils';
import * as dtUtils from './dataTableUtils';


('use strict');

/*Create Button */
export const createConfig = (state, editor, context) => {
    return [
        {
            extend: 'create',
            editor: editor,
            titleAttr: 'Create asset',
            action: function(event, dt) {
                //params for ajax request for create dialog
                let createDialogParams = {
                    _viewClass: state.createService,
                    resourceType: state.resourceType,
                    _base: swa.queryGraphURI,
                    _snippet: true
                };

                var searchParams = new URLSearchParams(location.search);

                let contextResource = searchParams.get('resource');

                if(!contextResource && location.hash){
                  contextResource = decodeURIComponent(location.hash.replace('#',''));
                }

                if(contextResource){
                  createDialogParams['contextResource'] = contextResource;
                }

                context.loadingMode(true); //enable loading indicator

                //request to get create dialog info from server
                let createDialogRequest = utils.postDataForEndpoint(createDialogParams);

                //get the create dialog
                Promise.resolve(createDialogRequest)
                    .then(
                        data => {
                            //get the current columns
                            let columns = dt.settings().init().columns;

                            //get the value of the currently existing label column
                            let resourceTypeLabel = columns.filter(function(obj) {
                                return obj.type === 'label';
                            })[0].title;

                            let dialogMarkupRequest = swa.populateConfirmDialog(
                                data,
                                'Create New ' + resourceTypeLabel,
                                function() {
                                    disableButtonOnPageLoadIfNeeded();
                                }
                            );

                            // wait for dialog action, then resolve or reject promise
                            Promise.resolve(dialogMarkupRequest).then(
                                dialogMarkup => {
                                    let resourceInfo = dtUtils.getResourceInfo(dialogMarkup);
                                    //parameters to pass to createService

                                    let metadata =
                                        '{"createdResource":"' +
                                        $('#uri-input').val() +
                                        $('#label-input').val() +
                                        '"}';

                                    let createResourceParams = {
                                        _viewClass: state.createResourceHandler
                                            ? state.createResourceHandler
                                            : 'swa:CreateResourceHandler',
                                        label: $('#label-input').val(),
                                        labelLang: $('#label-lang').val(),
                                        uri: $('#uri-input').val(),
                                        resourceType: resourceInfo.resourceType,
                                        metadata: metadata,
                                        _base: swa.queryGraphURI
                                    };

                                    $('input[data-property]').each(function(index, item){
                                        let property = $(item).attr('data-property'),
                                            value = $(item).val();

                                            if(value){
                                              value = value.replace(/^\</,'').replace(/\>$/,'');
                                              createResourceParams[property] = value;
                                            }
                                    });



                                    let createCallback = utils.postDataForEndpoint(
                                        createResourceParams
                                    );

                                    context.loadingMode(true);

                                    Promise.resolve(createCallback)
                                        .then(
                                            data => {
                                                if (!data.error && data.changed === true) {
                                                    //if an error wasn't returned, or if constraint violations weren't returned
                                                    let newRow = {}; //new row to be added to the table
                                                    let newRowLabel = createResourceParams.label; //label for new row
                                                    let newRowURI = createResourceParams.uri; //uri for new row

                                                    let changes = data.changes[data.rootResource];

                                                    if(changes){


                                                    let changeArray = Object.keys(changes);

                                                    //loop through each column
                                                    for (let i = 0; i < columns.length; i++) {
                                                        var currentColName = columns[i].data;
                                                        var currentColType = columns[i].type;

                                                        if (currentColName === 'uri') {
                                                            newRow[currentColName] = newRowURI;
                                                        } else if (currentColType === 'label') {
                                                            newRow[currentColName] = newRowLabel;
                                                        } else if (
                                                            currentColName === 'rdf:type' ||
                                                            currentColName === 'type' ||
                                                            currentColName === 'rdf%3Atype'
                                                        ) {
                                                            newRow[currentColName] = resourceInfo.typeLabel;
                                                        } else if (
                                                            currentColName === 'type[, ].label'
                                                        ) {
                                                            newRow.type = [
                                                                {
                                                                    label: resourceInfo.typeLabel
                                                                }
                                                            ];
                                                        } else if (
                                                            changeArray.indexOf(currentColType) > -1
                                                        ) {
                                                            //if the column type exists in the list of changes
                                                            //pull that value from the change result and add it to the new row
                                                            let colValue =
                                                                changes[
                                                                    changeArray[
                                                                        changeArray.indexOf(
                                                                            currentColType
                                                                        )
                                                                    ]
                                                                ];

                                                            var result = [];

                                                            colValue.forEach(entry => {
                                                                //remove datatype from entry
                                                                 if(entry.endsWith("^^xsd:dateTime")){
                                                                      result.push(entry.substring(
                                                                            1,
                                                                            entry.length - 15
                                                                        )
                                                                      );
                                                                }  //remove quotes from entry
                                                                else if(entry.startsWith("\"")){
                                                                    result.push(
                                                                        entry.substring(
                                                                            1,
                                                                            entry.length - 1
                                                                        )
                                                                    );
                                                                }
                                                                else{
                                                                    result.push(entry);
                                                                }
                                                            });

                                                            newRow[currentColName] = result.join(
                                                                ', '
                                                            );
                                                        } else {
                                                            //if the column type does not exist in the list of changes, enter empty value
                                                            newRow[currentColName] === '';
                                                        }
                                                    }

                                                    dt.rows().deselect();
                                                    //select the newly created row
                                                    dt.row
                                                        .add(newRow)
                                                        .select()
                                                        .draw()
                                                        .show()
                                                        .draw(false);
                                                      }

                                                    //wait for the resource pane to load with the new resource, then click edit button
                                                    var waitForPaneReload = waitForElementToExist(
                                                        document.body,
                                                        '.edit-button'
                                                    );

                                                    Promise.resolve(waitForPaneReload).then(
                                                        data => {
                                                            //once this is resolved, the edit button is ready to be clicked
                                                            if ($('.edit-button')[0]) {
                                                                $('.edit-button').click();
                                                            }
                                                        },
                                                        err => {
                                                            //console.error(err);
                                                        }
                                                    );
                                                } else {
                                                    let problemsArray = [];
                                                    if (data.error) {
                                                        problemsArray.push(data.error);
                                                    } else if (data.changed) {
                                                        for (
                                                            let i = 0;
                                                            i < data.validationResults.length;
                                                            i++
                                                        ) {
                                                            let problemURI =
                                                                data.validationResults[i].focusNode;
                                                            problemURI = problemURI.replace(
                                                                /[<>]/g,
                                                                ''
                                                            );
                                                            let problemMessage =
                                                                data.validationResults[i].message;
                                                            let error =
                                                                'Problem with ' +
                                                                problemURI +
                                                                ': ' +
                                                                problemMessage +
                                                                '<br/>';
                                                            problemsArray.push(error);
                                                        }
                                                    } else {
                                                        problemsArray.push('Error');
                                                    }
                                                    swa.populateModalDialog(
                                                        'Error, could not create resource: <br/>' +
                                                            problemsArray.join(' '),
                                                        'TopBraid Alert',
                                                        null
                                                    );
                                                }
                                            },
                                            err => {
                                                //console.error(err);
                                            }
                                        )
                                        .then(() => {
                                            context.loadingMode(false);
                                        }); //end createCallback
                                },
                                err => {
                                    if (err !== 'canceled') {
                                        //console.log(err);
                                    }
                                }
                            ); //end dialogMarkupRequest
                        },
                        err => {
                            //console.warn(err);
                        }
                    ) //end createDialogRequest
                    .then(() => {
                        context.loadingMode(false); //disable loading indicator after request has completed
                    });
            } //action
        }
    ];
};

/*Edit/batch edit button*/
export const editConfig = (state, editor, context) => {
    return [
        {
            extend: 'edit',
            editor: editor,
            text: 'Batch Edit',
            titleAttr: 'Edit all selected assets',
            action: function(event, dt) {
                let selectedItems = dtUtils.getSelectedRows(dt);
                let selectedURIs = dtUtils.getSelectedURIs(selectedItems);

                //[TBS-602]if we have less than 100 rows selected, let the batch edit go through, otherwise, fail
                if (selectedItems.count() > 100) {
                    swa.populateErrorModal(
                        'Sorry, you may only batch edit 100 resources at a time.  Please select fewer rows and try again.'
                    );
                    return;
                }

                context.loadingMode(true);

                let canBatchEditResourceParams = {
                    _viewClass: 'swa:CanBatchEditResourcesService',
                    resources: selectedURIs.join(' '),
                    _base: swa.queryGraphURI
                };

                let canBatchEditResource = utils.postDataForEndpoint(canBatchEditResourceParams);

                Promise.resolve(canBatchEditResource)
                    .then(
                        editableURIs => {
                            if (editableURIs.error) {
                                swa.populateErrorModal('Error: ' + editableURIs.error);
                                return;
                            }
                            if (editableURIs.length === 0) {
                                swa.populateErrorModal(
                                    'Error - All of the assets you are trying to edit contain read-only data.'
                                );
                                return;
                            }

                            var editValues = editableURIs.map(editableURIs => {
                                return editableURIs.URI;
                            });

                            //if we can only batch edit a subset of the data
                            if (editValues.length < selectedURIs.length) {
                                let confirmSubsetEdit = swa.populateConfirmDialog(
                                    'Warning: ' +
                                        (parseInt(selectedURIs.length) -
                                            parseInt(editValues.length)) +
                                        ' of the assets you are trying to edit contain read only data.  Please note that if you choose to proceed with this edit the read-only data will not be updated.',
                                    'TopBraid Warning'
                                );

                                Promise.resolve(confirmSubsetEdit).then(
                                    () => {
                                        let editDialog = swa.openMultiResourceEditDialog(
                                            editValues,
                                            state.resourceType
                                        );

                                        Promise.resolve(editDialog).then(
                                            () => {
                                                //success - the table automatically reloads to pick up any changes
                                                //can change this in the future to not need to reload the full table data
                                                //right now there doesn't seem to be the need
                                            },
                                            err => {
                                                swa.populateErrorModal('Edit Failed ' + err);
                                            }
                                        );
                                    },
                                    () => {
                                        //cancelled
                                    }
                                );
                            } else {
                                let editDialog = swa.openMultiResourceEditDialog(
                                    editValues,
                                    state.resourceType
                                );

                                Promise.resolve(editDialog).then(
                                    () => {
                                        //success - the table automatically reloads to pick up any changes
                                        //can change this in the future to not need to reload the full table data
                                        //right now there doesn't seem to be the need
                                    },
                                    err => {
                                        swa.populateErrorModal('Edit Failed ' + err);
                                    }
                                );
                            }
                        },
                        err => {
                            //canceled dialog
                            swa.populateErrorModal('Edit Failed ' + err);
                        }
                    )
                    .then(() => {
                        context.loadingMode(false);
                    });
            }
        }
    ];
};

/*Details view button */
export const detailsbutton = (state, context, editor) => {
    return {
        extend: 'selectedSingle',
        text: 'Details',
        titleAttr: 'View/Edit asset in a new tab',
        editor: editor,
        action: (e, dt) => {
            var url = window.location.href;
            var selectedItem = dtUtils.getSelectedRows(dt);
            if (selectedItem.count() !== 1) {
                swa.populateModalDialog(
                    'You must select a single resource from the table to view.'
                );
                return;
            } else {
                var projectGraph = selectedItem[0]['uri']
                    ? selectedItem[0]['uri']
                    : swa.queryGraphURI.substr(0, swa.queryGraphURI.length - 4);
                var hash = url.indexOf('#');

                if (hash > 0) {
                    url = url.substring(0, hash);
                }
                var q = url.indexOf('?');
                if (q > 0) {
                    url = url.substring(0, q);
                }

                url +=
                    '?_editorClass=teamwork:SimpleFormEditorApplication&resource=' +
                    encodeURIComponent(projectGraph);

                var list = [];
                dt
                    .rows()
                    .data()
                    .each(function(el, idx) {
                        list.push(el.uri);
                    });

                var detailsView = window.open(url, '_blank');

                detailsView.myList = list;
            }
        }
    };
};

/*Clone button*/
export const cloneConfig = (state, editor, context) => {
    return [
        {
            extend: 'selectedSingle',
            text: 'Clone',
            titleAttr: 'Create copy of selected asset',
            editor: editor,
            action: function(event, dt) {
                let columns = dt.settings().init().columns;
                let selectedItem = dtUtils.getSelectedRows(dt);
                let selectedURIs = dtUtils.getSelectedURIs(selectedItem);

                if (selectedItem.count() !== 1) {
                    swa.populateModalDialog(
                        'You must select a single resource from the table to clone.'
                    );
                    return;
                } else {
                    let createResourceParams = {
                        _viewClass: 'teamwork:CloneResourceHandler',
                        resource: selectedURIs.join(','),
                        _snippet: true,
                        _base: swa.queryGraphURI
                    };

                    let cloneCallback = utils.postDataForEndpoint(createResourceParams);

                    Promise.resolve(cloneCallback).then(
                        data => {
                            if (!data.error && data.changed === true) {
                                //if an error wasn't returned, or if constraint violations weren't returned
                                let newRowURI = data.rootResource; //uri for new row

                                let changes = Object.keys(data.changes).map(
                                    e => data.changes[e]
                                )[0]; //assumes only one change is returned on create
                                let changeKeys = Object.keys(changes);
                                let changeValues = Object.values(changes);

                                let newRow = JSON.parse(JSON.stringify(selectedItem[0]));
                                let labelIndex = changeKeys.indexOf(
                                    'http://www.w3.org/2000/01/rdf-schema#label'
                                );
                                let newRowLabel = '';
                                if (labelIndex && changeValues[labelIndex]) {
                                    newRowLabel = changeValues[labelIndex].join(' ');
                                }

                                console.log(changeValues);
                                console.log(newRowLabel);

                                newRow.uri = newRowURI;

                                for (let i = 0; i < columns.length; i++) {
                                    var currentColName = columns[i].data;
                                    var currentColType = columns[i].type;

                                    if (currentColType === 'label') {
                                        newRow[currentColName] = newRowLabel.substring(
                                            1,
                                            newRowLabel.length - 1
                                        );
                                    }
                                }

                                dt.rows().deselect();
                                dt.row
                                    .add(newRow)
                                    .select()
                                    .draw()
                                    .show()
                                    .draw(false);
                            } else {
                                let problemsArray = [];
                                if (data.error) {
                                    problemsArray.push(data.error);
                                } else if (data.changed) {
                                    for (let i = 0; i < data.validationResults.length; i++) {
                                        let problemURI = data.validationResults[i].focusNode;
                                        problemURI = problemURI.replace(/[<>]/g, '');
                                        let problemMessage = data.validationResults[i].message;
                                        let error =
                                            'Problem with ' +
                                            problemURI +
                                            ': ' +
                                            problemMessage +
                                            '<br/>';
                                        problemsArray.push(error);
                                    }
                                } else {
                                    problemsArray.push('Error');
                                }
                                swa.populateModalDialog(
                                    'Error, could not create resource: <br/>' +
                                        problemsArray.join(' '),
                                    'TopBraid Alert',
                                    null
                                );
                            }
                        },
                        err => {
                            //console.error(err);
                        }
                    );
                }
            }
        }
    ];
};

/*Delete button */
export const deleteConfig = (state, editor, context) => {
    return [
        {
            extend: 'remove',
            editor: editor,
            titleAttr: 'Delete all selected assets',
            action: function(event, dt) {
                //get currently selected rows and uris for the rows
                let selectedItems = dtUtils.getSelectedRows(dt);
                let selectedURIs = dtUtils.getSelectedURIs(selectedItems);

                let canDeleteResourceParams = {
                    _viewClass: 'swa:CanDeleteResourcesService',
                    resources: selectedURIs.join(' '),
                    _base: swa.queryGraphURI
                };

                context.loadingMode(true);

                let canDeleteResource = utils.postDataForEndpoint(canDeleteResourceParams);

                Promise.resolve(canDeleteResource)
                    .then(data => {
                        if (data.error) {
                            swa.populateErrorModal('Error: ' + data.error);
                            return;
                        }

                        let confirmDialog = swa.populateConfirmDialog(
                            'Are you sure you want to delete ' +
                                selectedItems.count() +
                                ' row(s) containing ' +
                                data.tripleCount +
                                ' statements'
                        );

                        Promise.resolve(confirmDialog).then(
                            () => {
                                context.loadingMode(true);

                                let deleteResourceParams = {
                                    _viewClass: 'swa:DefaultDeleteResourcesService',
                                    resources: selectedURIs.join(' '),
                                    _base: swa.queryGraphURI
                                };

                                let deleteResourceCall = utils.postDataForEndpoint(
                                    deleteResourceParams
                                );

                                Promise.resolve(deleteResourceCall)
                                    .then(
                                        () => {
                                            swa.populateModalDialog(
                                                'Delete successful - ' +
                                                    selectedItems.count() +
                                                    ' row(s) deleted'
                                            );
                                            dt
                                                .rows({ selected: true })
                                                .remove()
                                                .draw();

                                            //reload datatable component
                                        },
                                        err => {
                                            swa.populateErrorModal('Delete Failed ' + err);
                                        }
                                    ) //end deleteResourceCall
                                    .then(() => {
                                        context.loadingMode(false);
                                    });
                            },
                            err => {
                                //promise cancelled
                            }
                        ); //end confirmDialogCall
                    }) //end canDeleteResource
                    .then(() => {
                        context.loadingMode(false);
                    });
            }
        }
    ];
};

export const addButtons = (state, editor, context) => {
    let editorButtons = [];

    editorButtons = editorButtons.concat(createConfig(state, editor, context));

    if (state && state.hasEditButton) {
        editorButtons = editorButtons.concat(editConfig(state, editor, context));
    }

    editorButtons = editorButtons.concat(deleteConfig(state, editor, context));

    if ((context.props && context.props.hasCloneButton) || state.hasCloneButton) {
        editorButtons = editorButtons.concat(cloneConfig(state, editor, context));
    }

    return editorButtons;
};

/* EDITOR BUTTONS HELPER FUNCTIONS */
export const disableButtonOnPageLoadIfNeeded = () => {
    //set focus on label box, if it exists
    if ($('#label-input')[0]) {
        $('#label-input').focus();
    }

    //determine whether the class we're on is an abstract class, if so, disable submit button
    if ($('#type-select')[0] && $('#type-select')[0].options) {
        let selectedIndex = $('#type-select')[0].options.selectedIndex;
        let $option = $('#type-select')[0].options[selectedIndex];
        let isAbstractClass = $option.getAttribute('data-abstract');

        if (isAbstractClass) {
            $('.btn-confirm').attr('disabled', true);
        }
    }
};

/* Uses a MutationObserver to poll for changes on the dom - waiting for a specifc element to be added */
export const waitForElementToExist = (element, attributeName, rejectTime = 0) => {
    return new Promise((resolve, reject) => {
        let hasChanged = false;
        const observerConfig = { childList: true, subtree: true };
        const observer = new MutationObserver(mutations => {
            mutations.forEach(mutation => {
                var newNodes = mutation.addedNodes; // DOM NodeList

                if (newNodes !== null) {
                    // If there are new nodes added
                    var $nodes = $(newNodes); // jQuery set

                    $nodes.each(function() {
                        var $node = $(this);
                        //probably pass in as a parameter if we find other uses for this function
                        if ($node.hasClass('swa-window')) {
                            observer.disconnect();
                            resolve(true);
                        }
                    });
                }
            });
        });

        if (rejectTime > 0) {
            window.setTimeout(() => {
                if (!hasChanged) {
                    //console.log('rejecting');
                    reject(element);
                }
            }, rejectTime * 100);
        }

        observer.observe(element, observerConfig);
    });
};



