import React from 'react';
import ReactDOM from 'react-dom';
import GraphiQL from 'graphiql';
import fetch from 'isomorphic-fetch';
import $ from 'jquery';
import '../../../../node_modules/graphiql/graphiql.css';

export default class TBGraphiQL extends React.Component{

    constructor(props){
        super(props);
        this.state = {
            // REQUIRED:
            // `fetcher` must be provided in order for GraphiQL to operate
            fetcher: this.graphQLFetcher.bind(this),

            // OPTIONAL PARAMETERS
            // GraphQL artifacts
            query: undefined,
            variables: '',
            response: '',
            url: '',

            // GraphQL Schema
            // If `undefined` is provided, an introspection query is executed
            // using the fetcher.
            schema: undefined,

            // Useful to determine which operation to run
            // when there are multiple of them.
            operationName: null,
            storage: null,
            defaultQuery: undefined,

            // Custom Event Handlers
            onEditQuery: this.onEditQuery.bind(this),
            onEditVariables: this.onEditVariables.bind(this),
            onEditOperationName: this.onEditOperationName.bind(this),

            // GraphiQL automatically fills in leaf nodes when the query
            // does not provide them. Change this if your GraphQL Definitions
            // should behave differently than what's defined here:
            // (https://github.com/graphql/graphiql/blob/master/src/utility/fillLeafs.js#L75)
            getDefaultFieldNames: null
        };

    }

    graphQLFetcher(graphQLParams){
        return fetch(this.state.url, {
            method: 'post',
            headers: {
                'Accept': 'application/json',
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(graphQLParams),
            credentials: 'include',
        }).then(function (response){
            return response.text();
        }).then(function (responseBody){
            try {
                return JSON.parse(responseBody);
            } catch (error) {
                return responseBody;
            }
        });
    }

    onEditQuery(newQuery){
        this.setState({
            query : newQuery
        });
        updateURL({query:this.state.query, variables:this.state.variables, operationName:this.state.operationName});
    }

    onEditVariables(newVariables){
        this.setState({
            variables : newVariables
        });
        updateURL({query:this.state.query, variables:this.state.variables, operationName:this.state.operationName});
    }

    onEditOperationName(newOperationName){
        this.setState({
            operationName : newOperationName
        });
        updateURL({query:this.state.query, variables:this.state.variables, operationName:this.state.operationName});
    }

    handleClickPrettifyButton(event){
        const editor = this.graphiql.getQueryEditor();
        const currentText = editor.getValue();
        const { parse, print } = require('graphql');
        const prettyText = print(parse(currentText));
        editor.setValue(prettyText);
    }

    componentDidMount(){
        // Parse the search string to get url parameters.
        var search = window.location.search;
        var parameters = {};

        search.substr(1).split('&amp;').forEach(function (entry) {
            var eq = entry.indexOf('=');
            if (eq >= 0) {
                parameters[decodeURIComponent(entry.slice(0, eq))] =
                decodeURIComponent(entry.slice(eq + 1));
            }
        });

        if (parameters.variables || parameters.query) {
            try {
                var state = {
                    url : $('#graphiql').attr('data-url')
                };
                if(parameters.variables) {
                    // if variables was provided, try to format it.
                    state.variables = JSON.stringify(JSON.parse(parameters.variables), null, 2);
                }
                if(parameters.query) {
                    state.query = parameters.query;
                }
                this.setState(state);
            } catch (e) {
                // Do nothing, we want to display the invalid JSON as a string, rather
                // than present an error.
            }
        }
    }

    render() {
        return (
            <GraphiQL ref={c => { this.graphiql = c; }} {...this.state}>
                <GraphiQL.Logo> TopBraid GraphiQL </GraphiQL.Logo>
                <GraphiQL.Toolbar>
                    <GraphiQL.Button
                        onClick={this.handleClickPrettifyButton}
                        label="Prettify"
                        title="Prettify Query (Shift-Ctrl-P)"/>
                </GraphiQL.Toolbar>
                <GraphiQL.Footer />
            </GraphiQL>
        );
    }
}

// When the query and variables string is edited, update the URL bar so
// that it can be easily shared
var updateURL = (parameters) => {
    var newSearch = '?' + Object.keys(parameters).filter(function (key) {
        return Boolean(parameters[key]);
    }).map(function (key) {
        return encodeURIComponent(key) + '=' + encodeURIComponent(parameters[key]);
    }).join('&amp;');
    history.replaceState(null, null, newSearch);
};

$(document).ready( () =>{
    let graphiql = $('#graphiql');
    if(graphiql.length > 0){
        $('body').addClass('graphiqlBody');
        ReactDOM.render(<TBGraphiQL />, document.getElementById('graphiql'));
    }
});





