/*global  swa:true, gadgets*/
/*eslint no-undef: "error"*/

import React from 'react';
import ReactDOM from 'react-dom';
import $ from 'jquery';
import store from '../redux/store';
import { gadgets } from '../components/swa';
import * as registry from '../utils/componentRegistry';
import TopBraidSelect from './TopBraidSelect';


var buildSelect = (sel) => {

    let selector = sel || '[data-select]';
    let $tbSelect = $(selector);
    let component;

    $.each($tbSelect, function(idx, element) {
        if(!registry.hasComponent(element.id)){
            component = ReactDOM.render(<TopBraidSelect domReference={element} store={store} />, element);
            registry.addComponent(element.id, component);
        }
        else{
            registry.destroyComponent($(element));
            component = ReactDOM.render(<TopBraidSelect domReference={element} store={store} />, element);
            registry.addComponent(element.id, component);
        }

    });
};

// build any tables that exist as part of markup delivered by the server
$(document).ready(() => {
    buildSelect();
});

