    navigateToEditor = function(editorLink, resourceType, resource) {
        var baseURL = location.protocol + '//' + location.host;
        var slashIndex = location.pathname.lastIndexOf('/');
        var pathname = location.pathname.substring(0,slashIndex);

        var newURL = baseURL + pathname + '/' + editorLink + '?resourceType=' + resourceType + '#' + resource;

        window.open(newURL);
    },
    onPressLaunchExternal = function(element) {
        if (!element.resourceType || element.resourceType == 'undefined') {
            swa.populateModalDialog(
                `The 'type' for the selected element <strong><mark>${
                    element.label
                }</mark></strong> could not be determined, navigation to the EDG editor is not possible.`
            );
            return;
        }

        if (element.resource && element.resourceType) {
            if (!swa.lineagegram.editorLink) {
                var params = {
                    _base: swa.queryGraphURI,
                    _viewClass: 'edg:DefiningGraphForResource',
                    resource: decodeURIComponent(element.resource)
                };

                var $jqXHR = $.ajax({
                    url: swa.server + swa.servlet,
                    data: params,
                    method: 'get',
                    dataType: 'json'
                });

                Promise.resolve($jqXHR).then(function(response) {
                    if (response && response.data) {
                        var definingGraph = response.data[0];

                        navigateToEditor(
                            definingGraph.editorLink,
                            element.resourceType,
                            element.resource
                        );
                    }
                });
            } else {
                navigateToEditor(
                    swa.lineagegram.editorLink,
                    element.resourceType,
                    element.resource
                );
            }
        } else {
            swa.populateModalDialog('This action cannot be completed due to an unbound resource.');
        }
    },
