    initAutoComplete = function() {
        $('#search').autocomplete({
            source: function(request, callback) {
                var result = lineageGram
                    .getGraphModel()
                    .nodes.filter(function(node) {
                        return node.label.toLowerCase().indexOf(request.term.toLowerCase()) !== -1;
                    })
                    .map(function(node) {
                        return { label: node.label, value: node.id };
                    });
                callback(result);
            },
            select: function(event, selectedElement) {
                event.preventDefault();
                searchObj = selectedElement.item;
                lineageGram.setSelectedElement(searchObj.value);
                this.value = searchObj.label;
            },
            focus: function(event, selectedElement) {
                event.preventDefault();
                searchObj = selectedElement.item;
                this.value = searchObj.label;
                document.getElementById('tqLgSearchButton').disabled = false;
            },
            search: function() {
                searchObj = null;
                document.getElementById('tqLgSearchButton').disabled = true;
            }
        });
    },
    correctBackdrops = function(selector, backdrops) {
        const element = document.querySelector(selector);
        if (!element) return;
        const size = element.getBBox();
        backdrops['bottom'][0].style.top =
            'calc(' + size.height + 'px + ' + backdrops['top'][0].style.height + ')';
        backdrops['left'][0].style.height = size.height + 'px';
        backdrops['right'][0].style.height = size.height + 'px';
        backdrops['right'][0].style.left =
            'calc(' + size.width + 'px + ' + backdrops['right'][0].style.left + ')';
    },
